          text: `Federal Democratic Republic of Ethiopia - Ministry of Education Curriculum
Unit 4: Quadratic Equations and Inequalities
Section 4.3: The Discriminant and Nature of Real Roots

A standard quadratic equation is an equation that can be written in the form:
ax² + bx + c = 0, where a, b, c ∈ ℝ and a ≠ 0.

The solutions are given by the Quadratic Formula:
x = (-b ± √(b² - 4ac)) / (2a)

The quantity under the square root sign is called the Discriminant, denoted by the Greek letter capital Delta (Δ):
Δ = b² - 4ac

The value of the discriminant determines the number and nature of the solutions:
1. If Δ > 0 (b² - 4ac > 0):
   The equation has two distinct real roots:
   x₁ = (-b + √Δ) / (2a)   and   x₂ = (-b - √Δ) / (2a).

2. If Δ = 0 (b² - 4ac = 0):
   The equation has exactly one real repeated (double) root:
   x = -b / (2a).

3. If Δ < 0 (b² - 4ac < 0):
   The square root of a negative real number is not a real number; therefore, the equation has no real roots (it has two conjugate complex roots).

Worked Example 4.12:
Determine the value of the constant k for which the quadratic equation 2x² - 8x + k = 0 has real and equal roots.
Solution:
For real and equal roots, the discriminant must satisfy Δ = 0.
Here a = 2, b = -8, c = k.
Δ = b² - 4ac = (-8)² - 4(2)(k) = 64 - 8k
Setting Δ = 0:
64 - 8k = 0  =>  8k = 64  =>  k = 8.
Thus, when k = 8, the equation becomes 2x² - 8x + 8 = 0, or 2(x - 2)² = 0, which has the repeated root x = 2.`
