      "option_d": "0.95 mm",
      "correct_answer": "A",
      "explanation": "### Thermal Physics: Linear Thermal Expansion\n\n**1. Physical Principle:**\nWhen a solid material under goes a temperature change $\\Delta T$, its change in length $\\Delta L$ is directly proportional to its initial length $L_0$, the temperature variation $\\Delta T$, and its coefficient of linear expansion $\\alpha$:\n$$\\Delta L = L_0 cdot alpha cdot Delta T$$\n\n**2. Step-by-Step Calculation:**\nGiven:\n* Initial length: $L_0 = 1.0\\text{ m}$\n* Temperature change: $\\Delta T = T_f - T_i = 100^\\circ\\text{C} - 0^\\circ\\text{C} = 100\\text{ K}$ (or $100^\\circ\\text{C}$)\n* Coefficient of linear expansion for brass: $\\alpha = 1.9 imes 10^{-5}\\text{ K}^{-1}$\n\nSubstitute into the formula:\n$$\\Delta L = (1.0\\text{ m}) imes (1.9 imes 10^{-5}\\text{ K}^{-1}) imes (100\\text{ K})$$\n$$\\Delta L = 1.9 imes 10^{-3}\\text{ m}$$\nConverting meters to millimeters ($1\\text{ m} = 1000\\text{ mm}$):\n$$\\Delta L = 1.9 imes 10^{-3} imes 10^3\\text{ mm} = 1.9\\text{ mm}$$\n\n**3. Conclusion:**\nThe elongation of the brass rod when heated from $0^\\circ\\text{C}$ to $100^\\circ\\text{C}$ is $1.9\\text{ mm}$ ($0.0019\\text{ m}$), which corresponds to **Choice A**.",
