      "question_number": 53,
      "question_text": "If the apothem and radius of a regular 7-sided polygon are respectively $8\\text{ cm}$ and $2\\sqrt{59}\\text{ cm}$, then what is the area of the polygon in $\\text{cm}^{2}$?",
