      "id": "q-exam-entrance-1789625998133-1",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 1,
      "question_text": "Consider the data: 11, 13, 15, 17, 19, 21. Which one of the following is the mean deviation from\nthe mean?",
      "option_a": "4",
      "option_b": "3.5",
      "option_c": "4.5",
      "option_d": "3",
      "correct_answer": "D",
      "answer_status": "admin_verified",
      "explanation": "### Explanation: Mean Deviation from the Mean\n\nThe **mean deviation from the mean** is a measure of dispers i on that calculates the average of the absolute differences between each data point and the arithmetic mean of the data set.\n\n#### Step-by-Step Derivation:\n\n**Step 1: Calculate the Arithmetic Mean ($\\bar{x}$)**\nThe mean is the sum of all observations divided by the number of observations ($n$). Given data: $11, 13, 15, 17, 19, 21$\nNumber of observations ($n$) = $6$\n\n$$\\bar{x} = \\frac{11 + 13 + 15 + 17 + 19 + 21}{6} = \\frac{96}{6} = 16$$\n\n**Step 2: Calculate the absolute deviations from the mean $|x_i - \\bar{x}|$**\nWe subtract the mean ($16$) from each data point and take the absolute value:\n* $|11 - 16| = |-5| = 5$\n* $|13 - 16| = |-3| = 3$\n* $|15 - 16| = |-1| = 1$\n* $|17 - 16| = |1| = 1$\n* $|19 - 16| = |3| = 3$\n* $|21 - 16| = |5| = 5$\n\n**Step 3: Calculate the Mean Deviation (MD)**\nThe mean deviation is the average of these absolute differences:\n\nMean Deviation (MD) = (Sum of absolute deviations) / n\nMD = (5 + 3 + 1 + 1 + 3 + 5) / 6\nMD = 18 / 6 = 3\n\n#### Conclusion:\nBy calculating the average of the absolute differences from the mean, we arrive at a value of $3$. Therefore, the correct option is **D**.",
