      "id": "q-exam-entrance-1789625998133-2",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 2,
      "question_text": "Consider the quadrilateral ABCD where A=(0,0), B=(−1,1)), C=(0,2) and D=(2,2). Which one of\nthe following is true?",
      "option_a": "CD is perpendicular to AB.",
      "option_b": "BC is parallel to AD.",
      "option_c": "CD is perpendicular to BE.",
      "option_d": "AB is parallel to CD.",
      "correct_answer": "B",
      "answer_status": "admin_verified",
      "explanation": "To determine the proper ties of quadrilateral $ABCD$, we must analyze the slopes of its sides. In coordinate geometry, two lines are **parallel** if their slopes are equal ($m_1 = m_2$), and they are **perpendicular** if the product of their slopes is $-1$ ($m_1 \\cdot m_2 = -1$). The slope $m$ between two points $(x_1, y_1)$ and $(x_2, y_2)$ is calculated as:\n$$m = \\frac{y_2 - y_1}{x_2 - x_1}$$\n\n**Step-by-step derivation:**\n\n1. **Calculate the slope of $BC$:**\n Points are $B(-1, 1)$ and $C (0, 2)$.\n $$m_{BC} = \\frac{2 - 1}{0 - (-1)} = \\frac{1}{1} = 1$$\n\n2. **Calculate the slope of $AD$:**\n Points are $A (0, 0)$ and $D (2, 2)$.\n $$m_{AD} = \\frac{2 - 0}{2 - 0} = \\frac{2}{2} = 1$$\n\n3. **Compare the slopes:**\n Since $m_{BC} = 1$ and $m_{AD} = 1$, the slopes are equal. By definition, lines with equal slopes are parallel. Therefore, $BC \\parallel AD$.\n\n4. **Evaluate other options (for verification):**\n * Slope of $AB$: $m_{AB} = \\frac{1 - 0}{-1 - 0} = -1$.\n * Slope of $CD$: $m_{CD} = \\frac{2 - 2}{2 - 0} = 0$.\n * Since $m_{AB} \\neq m_{CD}$, $AB$ is not parallel to $CD$ (eliminating D).\n * Since $m_{AB} \\cdot m_{CD} = -1 \\cdot 0 = 0 \\neq -1$, $CD$ is not perpendicular to $AB$ (eliminating A).\n\n**Conclusion:**\nBecause the slope of $BC$ is equal to the slope of $AD$, the segments are parallel. Thus, option **B** is the correct statement.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Relations & Functions",
