      "id": "q-exam-entrance-1789625998133-5",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 5,
      "question_text": "Which one of the following is a source of cash loan?",
      "option_a": "Non-government organization to alleviate public problems.",
      "option_b": "Investors involved in home construction for a community.",
      "option_c": "Group of investors committed to drilling out under ground water.",
      "option_d": "A money line group investing in health improvement sectors.",
      "correct_answer": "D",
      "answer_status": "admin_verified",
      "explanation": "### Explanation of Cash Loan Sources\n\nIn the context of economics and financial studies, a **cash loan** is a financial transaction where a lender provides a specific amount of money to a borrower, with the expectation that the principal amount will be repaid, typically with interest, over a defined period. Unlike grants or subsidies, which are non-repayable, a loan is a debt instrument. To identify the correct source of a cash loan among the options, we must evaluate the nature of the entities involved:\n\n1. **Analyze the Nature of the Entities:**\n * **Options A, B, and C:** These options describe entities (NGOs, community home builders, and water-drilling groups) that typically operate based on **grants, public funding, or social welfare man dates**. Their primary goal is the provision of public goods or services (infrastructure, water, social relief) rather than the provision of credit or financial capital for profit or debt-based lending.\n * **Option D:** A \" money line group \" refers to a financial entity or a group of investors whose primary function is the management and allocation of capital. When such a group invests in sectors—even social sectors like health improvement—they are acting as **financial intermediaries**.\n\n2. **Logical Derivation:**\n * A loan requires a lender-borrower relationship governed by financial terms. \n * NGOs (Option A) generally provide aid, not loans.\n * Community-based construction and utility projects (Options B and C) are usually funded by government budgets or non-profit donations.\n * Financial groups (Option D) operate within the credit market. By \" investing \" in sectors through a \" money line,\" they are providing the necessary liquidity (cash) that functions as a loan or credit facility to be repaid by the health sector entities.\n\n**Conclusion:**\nChoice **D** is the correct answer because a \" money line group \" represents a financial institution or investment entity capable of extending credit, whereas the other options describe organizations focused on social welfare, infrastructure, or public service provision rather than financial lending.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Relations & Functions",
      "section_instruction": "Answer question 5 based on Unit 1: Relations and Functions standards.",
