          "id": "q-exam-entrance-1789625998133-6",
          "exam_id": "exam-entrance-1789625998133",
          "question_number": 6,
          "question_text": "What is the average rate of change of $y = f(x)$ with respect to $x$ on the interval $[a, b]$?",
          "option_a": "$\\frac{f(a) - f(b)}{b - a}$",
          "option_b": "$\\frac{f(b) + f(a)}{b - a}$",
          "option_c": "$\\frac{f(b) - f(a)}{a - b}$",
          "option_d": "$\\frac{f(b) - f(a)}{b - a}$",
          "correct_answer": "D",
          "answer_status": "admin_verified",
          "explanation": "The average rate of change of a function $f (x)$ over a closed interval $[a, b]$ represents the slope of the secant line passing through the points $(a, f (a))$ and $(b, f (b))$ on the graph of the function. Conceptually, it measures the average amount by which the out put $y$ changes per unit change in the input $x$ over that specific interval.\n\n### Step-by-Step Derivation:\n\n1. **Identify the coordinates:** For a function $y = f (x)$, the points on the curve corresponding to the end points of the interval $[a, b]$ are $(a, f (a))$ and $(b, f (b))$.\n2. **Calculate the change in $y$ ($\\Delta y$):** The change in the function's out put is the difference between the values at the end points:\n $$\\Delta y = f (b) - f (a)$$\n3. **Calculate the change in $x$ ($\\Delta x$):** The change in the input is the difference between the end points of the interval:\n $$\\Delta x = b - a$$\n4. **Formulate the ratio:** The average rate of change is defined as the ratio of the change in $y$ to the change in $x$:\n $$\\text{Average Rate of Change} = \\frac{\\Delta y}{\\Delta x} = \\frac{f (b) - f (a)}{b - a}$$\n\n### Conclusion:\nThe formula $\\frac{f (b) - f (a)}{b - a}$ represents the constant slope required to connect the two points $(a, f (a))$ and $(b, f (b))$. Since this expression matches the definition of the average rate of change, and assuming Option D corresponds to this mathematical expression, it is the correct choice.",
          "grade_id": "grade-12-natural",
          "subject_id": "subj-math",
          "topic_name": "Differential Calculus & Derivatives",
          "section_instruction": "Answer question 6 based on Unit 3: Introduction to Differential Calculus standards.",
          "instruction_category": "Differential Calculus & Derivatives",
          "difficulty": "Easy",
