      "id": "q-exam-entrance-1789625998133-7",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 7,
      "question_text": "Which one of the following sets is the solution of log3x+log3 (x−2)=1?",
      "option_a": "{−1,3}",
      "option_b": "{3}",
      "option_c": "{2}",
      "option_d": "{0,2}",
      "correct_answer": "B",
      "answer_status": "admin_verified",
      "explanation": "To solve the logarithmic equation $\\log_{3}x + \\log_{3}(x-2) = 1$, we must apply the fundamental proper ties of logarithms while respecting the domain constraints of the logarithmic function.\n\n### 1. Domain Constraints\nA logarithm $\\log_{b}(A)$ is defined only when $A > 0$. Therefore, we must satisfy:\n* $x > 0$\n* $x - 2 > 0 \\implies x > 2$\nCombining these, the solution must satisfy **$x > 2$**.\n\n### 2. Step-by-Step Derivation\n**Step 1: Use the Product Property of Logarithms.**\nThe sum of two logarithms with the same base is the logarithm of the product of their arguments: $\\log_{b}(M) + \\log_{b}(N) = \\log_{b}(M \\cdot N)$.\n$$\\log_{3}(x (x - 2)) = 1$$\n\n**Step 2: Convert to Exponential Form.**\nThe equation $\\log_{b}(A) = C$ is equivalent to $b^C = A$.\n$$x (x - 2) = 3^1$$\n$$x^2 - 2x = 3$$\n\n**Step 3: Solve the Quadratic Equation.**\nRearrange the equation into standard form ($ax^2 + bx + c = 0$):\n$$x^2 - 2x - 3 = 0$$\nFactor the quadratic expression:\n$$(x - 3)(x + 1) = 0$$\nThis gives two potential solutions: $x = 3$ or $x = -1$.\n\n### 3. Verification and Conclusion\nWe must check these values against our domain constraint ($x > 2$):\n* For $x = -1$: Since $-1 \\ngtr 2$, this is an **extraneous solution**.\n* For $x = 3$: Since $3 > 2$, this is a **valid solution**. Because only $x = 3$ satisfies the original equation, the solution set is $\\{3\\}$. Therefore, **Choice B** is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Rational Expressions & Functions",
      "section_instruction": "Answer question 7 based on Unit 2: Rational Expressions and Rational Functions standards.",
      "instruction_category": "Rational Expressions & Functions",
      "difficulty": "Easy",
      "extraction_method": "high_fidelity_pdf_reparse",
      "extraction_confidence": 1,
      "needs_review": false,
      "is_ai_generated": false,
      "exam_title": "2018 E.C. Mathematics EUEE Exam",
      "exam_year": 2018,
