      "id": "q-exam-entrance-1789625998133-8",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 8,
      "question_text": "Given the functions f (x)=ax2and g (x)=ax2+c, for a<0 and c>0. Which of the following statements\nis true about the graph of f and g?",
      "option_a": "The graph of f is an upward parabola, and the graph of g is obtained from that of f by shifting\nit downward by cc units.",
      "option_b": "The graph of f is a downward parabola, and the graph of g is obtained from that of f by\nshifting it to the right by cc units.",
      "option_c": "The graph of f is an upward parabola, and the graph of g is obtained from that of f by shifting\nit upward by cc units.",
      "option_d": "The graph of f is a downward parabola, and the graph of g is obtained from that of f by\nshifting it upward by cc units.",
      "correct_answer": "D",
      "answer_status": "admin_verified",
      "explanation": "To understand the relationship between the functions $f (x) = ax^2$ and $g (x) = ax^2 + c$, we must analyze the proper ties of quadratic functions and the effects of vertical transform at i ons.\n\n### 1. Analyzing the Shape of $f (x)$\nThe function $f (x) = ax^2$ is a standard quadratic function. The coefficient $a$ determines the direction of the parabola:\n* If $a > 0$, the parabola opens upward.\n* If $a < 0$, the parabola opens downward. Since the problem states $a < 0$, the graph of $f (x)$ is a **downward-opening parabola** with its vertex at the origin $(0, 0)$.\n\n### 2. Analyzing the Transform at i on to $g (x)$\nThe function $g (x)$ is defined as $g (x) = f (x) + c$. In function transform at i on theory, adding a constant $c$ to the out put of a function results in a vertical shift:\n* If $c > 0$, the graph is shifted **upward** by $c$ units.\n* If $c < 0$, the graph is shifted **downward** by $|c|$ units. Given that $c > 0$, the graph of $g (x) = ax^2 + c$ is obtained by taking the graph of $f (x)$ and shifting every point on it upward by $c$ units. Consequently, the vertex of $g (x)$ moves from $(0, 0)$ to $(0, c)$.\n\n### 3. Conclusion\nBy combining these observations:\n* The graph of $f (x)$ is a downward parabola because $a < 0$.\n* The graph of $g (x)$ is a vertical translation of $f (x)$ shifted upward by $c$ units because $c > 0$. Comparing this to the given options, **Choice D** correctly i dent if ies that the graph of $f$ is a downward parabola and the graph of $g$ is obtained by shifting $f$ upward by $c$ units.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Relations & Functions",
      "section_instruction": "Answer question 8 based on Unit 1: Relations and Functions standards.",
      "instruction_category": "Relations & Functions",
      "difficulty": "Easy",
