          "id": "q-exam-entrance-1789625998133-10",
          "exam_id": "exam-entrance-1789625998133",
          "question_number": 10,
          "question_text": "Consider the figure given below: Which one of the following vectors is equal to $\\vec{AB} + \\vec{CD} + \\vec{BC}$?",
          "option_a": "$\\vec{AC}$",
          "option_b": "$\\vec{BD}$",
          "option_c": "$\\vec{AD}$",
          "option_d": "$\\vec{DA}$",
          "correct_answer": "C",
          "answer_status": "admin_verified",
          "explanation": "To solve this problem, we rely on the **Vector Add it i on Law (Triangle Law)**, which states that for any three points $A, B,$ and $C$, the sum of vectors is defined by the head-to-tail connection: $\\vec{AB} + \\vec{BC} = \\vec{AC}$.\n\n### Step-by-Step Derivation:\n\n1. **Analyze the Expression:** We are asked to simplify the vector sum:\n $$\\vec{S} = \\vec{AB} + \\vec{CD} + \\vec{BC}$$\n\n2. **Apply the Commutative Property:** Vector add it i on is commutative, meaning we can rearrange the terms to group vectors that share a common point (where the head of one vector meets the tail of another). Let’s rearrange the expression:\n $$\\vec{S} = \\vec{AB} + \\vec{BC} + \\vec{CD}$$\n\n3. **Apply the Triangle Law (First Step):** According to the triangle law, adding $\\vec{AB}$ and $\\vec{BC}$ results in a single vector that starts at the tail of the first and ends at the head of the second:\n $$\\vec{AB} + \\vec{BC} = \\vec{AC}$$\n\n4. **Apply the Triangle Law (Second Step):** Now, substitute this result back into our expression:\n $$\\vec{S} = (\\vec{AB} + \\vec{BC}) + \\vec{CD}$$\n $$\\vec{S} = \\vec{AC} + \\vec{CD}$$\n\n5. **Final Simplification:** Applying the triangle law once more to $\\vec{AC} + \\vec{CD}$, we connect the start of the first vector ($A$) to the end of the second vector ($D$):\n $$\\vec{AC} + \\vec{CD} = \\vec{AD}$$\n\n### Conclusion:\nBy rearranging the terms to follow the head-to-tail path, we find that the sum of the vectors is equivalent to the displacement vector from the initial point $A$ to the final point $D$. Therefore, the resultant vector is $\\vec{AD}$. Since Option C represents the vector $\\vec{AD}$, it is the correct answer.",
          "grade_id": "grade-12-natural",
          "subject_id": "subj-math",
          "topic_name": "Vectors in 2D & 3D Space",
          "section_instruction": "Answer question 10 based on Unit 5: Vectors standards.",
          "instruction_category": "Vectors in 2D & 3D Space",
          "difficulty": "Easy",
          "extraction_method": "high_fidelity_pdf_reparse",
          "extraction_confidence": 1,
          "needs_review": false,
          "is_ai_generated": false,
