      "id": "q-exam-entrance-1789625998133-11",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 11,
      "question_text": "Which one of the following equations represents a line that passes through the points (2, -1) and (-3, 4)?",
      "option_a": "x+y−1=0",
      "option_b": "x+y+1=0",
      "option_c": "x−y−1=0",
      "option_d": "x−y+1=0\n\n2018 Maths",
      "correct_answer": "A",
      "answer_status": "admin_verified",
      "explanation": "To find the equation of a line passing through two points $(x_1, y_1)$ and $(x_2, y_2)$, we use the point-slope form or the two-point form of a linear equation.\n\n### Step 1: Calculate the slope ($m$) The slope $m$ of a line passing through $(2, -1)$ and $(-3, 4)$ is calculated using the formula:\n$$m = \\frac{y_2 - y_1}{x_2 - x_1}$$\nSubstituting the given coordinates:\n$$m = \\frac{4 - (-1)}{-3 - 2} = \\frac{4 + 1}{-5} = \\frac{5}{-5} = -1$$\n\n### Step 2: Use the point-slope form\nThe point-slope form is given by $y - y_1 = m (x - x_1)$. Using the point $(2, -1)$ and $m = -1$:\n$$y - (-1) = -1 (x - 2)$$\n$$y + 1 = -x + 2$$\n\n### Step 3: Rearrange into the general form ($Ax + By + C = 0$) To match the options provided, we move all terms to one side of the equation:\n$$x + y + 1 - 2 = 0$$\n$$x + y - 1 = 0$$\n\n### Verification\nWe can verify this by checking if both points satisfy the equation $x + y - 1 = 0$:\n* For $(2, -1)$: $2 + (-1) - 1 = 2 - 1 - 1 = 0$. (Correct)\n* For $(-3, 4)$: $-3 + 4 - 1 = 1 - 1 = 0$. (Correct) Since the equation $x + y - 1 = 0$ satisfies both points, it is the correct represent at i on of the line. Therefore, **Choice A** is the correct answer.",
