      "id": "q-exam-entrance-1789625998133-12",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 12,
      "question_text": "What is the coefficient of x3y4 in the expansion of (x−2y) 7",
      "option_a": "35",
      "option_b": "70",
      "option_c": "560",
      "option_d": "-280",
      "correct_answer": "C",
      "answer_status": "admin_verified",
      "explanation": "To find the coefficient of a specific term in a binomial expansion, we use the **Binomial Theorem**. For any binomial $(a + b)^n$, the general term in the expansion is given by the formula:\n\n$$T_{k+1} = \\binom{n}{k} a^{n-k} b^k$$\n\nWhere:\n* $n$ is the power of the binomial.\n* $k$ is the index of the term (ranging from $0$ to $n$).\n* $\\binom{n}{k} = \\frac{n!}{k!(n-k)!}$ is the binomial coefficient.\n\n### Step-by-Step Derivation:\n\n**1. Identify the variables:**\nGiven the expression $(x - 2y)^7$, we have:\n* $a = x$\n* $b = -2y$\n* $n = 7$\n\n**2. Set up the general term:**\nWe want the term containing $x^3y^4$. Comparing this to the general form $a^{n-k}b^k$, we see that $x^{7-k} = x^3$, which implies $7-k = 3$, so **$k = 4$**.\n\n**3. Substitute the values into the formula:**\nUsing $k = 4$:\n$$T_{4+1} = \\binom{7}{4} (x)^{7-4} (-2y)^4$$\n\n**4. Calculate the components:**\n* **Binomial coefficient:** $\\binom{7}{4} = \\binom{7}{3} = \\frac{7 \\times 6 \\times 5}{3 \\times 2 \\times 1} = 35$\n* **Powers:** $(x)^3 = x^3$ and $(-2y)^4 = (-2)^4 y^4 = 16y^4$\n\n**5. Combine the results:**\n$$T_5 = 35 \\times x^3 \\times 16y^4$$\n$$T_5 = (35 \\times 16) x^3 y^4$$\n$$T_5 = 560 x^3 y^4$$\n\n### Conclusion:\nThe coefficient of $x^3y^4$ is the numerical value multiplying the variables, which is $560$. Therefore, **Choice C** is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Matrices & Systems of Linear Equations",
      "section_instruction": "Answer question 12 based on Unit 3: Matrices standards.",
      "instruction_category": "Matrices & Systems of Linear Equations",
      "difficulty": "Easy",
      "extraction_method": "high_fidelity_pdf_reparse",
