      "id": "q-exam-entrance-1789625998133-13",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 13,
      "question_text": "Which one of the following is NOT a power function?",
      "option_a": "f (x)=x3",
      "option_b": "f (x)=3x",
      "option_c": "f (x)=4x−6",
      "option_d": "f (x)=7x−1/3",
      "correct_answer": "C",
      "answer_status": "admin_verified",
      "explanation": "### Understanding Power Functions\n\nA **power function** is a function of the form:\n$$f (x) = ax^n$$\nwhere $a$ and $n$ are non-zero constant real numbers. In this definition, $a$ is the coefficient and $n$ is the exponent (or power). The key characteristic is that the variable $x$ is the **base** and the exponent $n$ is a **fixed constant**.\n\n### Step-by-Step Analysis\n\nTo determine which option is not a power function, we compare each given function to the standard form $f (x) = ax^n$:\n\n1. **Option A: $f (x) = x^3$**\n This can be written as $f (x) = 1 \\cdot x^3$. Here, $a = 1$ and $n = 3$. Since both are constants, this is a power function.\n\n2. **Option B: $f (x) = 3^x$**\n *(Note: Based on standard mathematical not at i on for this type of problem, $3^x$ is an exponential function, not a power function. However, if the expression is $f (x) = 3x^1$, it is a power function. Given the context of the options, we evaluate the structure of the exponent.)*\n\n3. **Option C: $f (x) = 4x - 6$**\n This is a **linear function** (a polynomial of degree 1). A power function must consist of a single term where the variable is raised to a constant power. Because this expression involves subtraction of a constant term ($-6$), it does not fit the form $ax^n$. It is a sum/difference of terms, not a single power term.\n\n4. **Option D: $f (x) = 7x^{-1/3}$**\n Here, $a = 7$ and $n = -1/3$. Since both are constants, this fits the definition of a power function perfectly.\n\n### Conclusion\nChoice **C** is the correct answer because $f (x) = 4x - 6$ is a linear polynomial, not a power function. A power function must be a single term of the form $ax^n$.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Matrices & Systems of Linear Equations",
      "section_instruction": "Answer question 13 based on Unit 3: Matrices standards.",
      "instruction_category": "Matrices & Systems of Linear Equations",
      "difficulty": "Easy",
      "extraction_method": "high_fidelity_pdf_reparse",
      "extraction_confidence": 1,
