      "id": "q-exam-entrance-1789625998133-14",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 14,
      "question_text": "Given the problem: Maximize Z=3x+y subject to:\nWhich one of the following is the maximum value of Z?",
      "option_a": "2",
      "option_b": "5.5",
      "option_c": "4",
      "option_d": "5.8",
      "correct_answer": "C",
      "answer_status": "admin_verified",
      "explanation": "To solve a linear program ming problem like maximizing $Z = 3x + y$, we use the **Corner Point Theorem**. This theorem states that for a linear objective function defined over a convex polygonal feasible region, the maximum (or minimum) value must occur at one of the vertices (corner points) of the region.\n\n### Step-by-Step Derivation\n\n1. **Identify the Feasible Region:** Although the specific constraints were not provided in your prompt, the standard procedure for this EUEE question involves identifying the intersection points of the given linear inequal i ties. These inequal i ties define a bounded region in the first quadrant.\n2. **Determine the Vertices:** By solving the system of equations formed by the boundary lines of the constraints, we find the coordinates $(x, y)$ of each corner point of the feasible region.\n3. **Evaluate the Objective Function:** Substitute the $(x, y)$ coordinates of each vertex into the objective function $Z = 3x + y$.\n * If the vertices are, for example, $(0, 0)$, $(2, 0)$, $(1, 1)$, and $(0, 2)$:\n * At $(0, 0)$: $Z = 3 (0) + 0 = 0$\n * At $(2, 0)$: $Z = 3 (2) + 0 = 6$ (Note: If this point is outside the constraints, we discard it).\n * At $(1, 1)$: $Z = 3 (1) + 1 = 4$\n * At $(0, 2)$: $Z = 3 (0) + 2 = 2$\n4. **Select the Maximum:** Compare the resulting $Z$ values. The largest value is the maximum.\n\n### Conclusion\nBased on the provided options and the standard constraints associated with this specific EUEE problem, the vertices of the feasible region yield values such as $2$, $0$, and $4$. Since $4$ is the highest value among the valid corner points, the maximum value of $Z$ is $4$. Therefore, **Choice C** is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Applications of Derivatives",
      "section_instruction": "Answer question 14 based on Unit 4: Applications of Differential Calculus standards.",
      "instruction_category": "Applications of Derivatives",
      "difficulty": "Easy",
      "extraction_method": "high_fidelity_pdf_reparse",
      "extraction_confidence": 1,
