          "id": "q-exam-entrance-1789625998133-17",
          "exam_id": "exam-entrance-1789625998133",
          "question_number": 17,
          "question_text": "Consider the graph of a polynomial function below. Which one of the following functions represents the graph with $x$-intercepts at $-1, 0, 1$?",
          "option_a": "$f(x) = x^3 + x + 1$",
          "option_b": "$f(x) = x^3 - x + 1$",
          "option_c": "$f(x) = x^3 - x$",
          "option_d": "$f(x) = x^3 + x$",
          "correct_answer": "C",
          "answer_status": "admin_verified",
          "explanation": "To determine which polynomial function represents a given graph, we must analyze the key features of the graph: its **x-intercepts** (roots) and its **end behavior**.\n\n### Step-by-Step Analysis\n\n**1. Identify the x-intercepts:**\nThe x-intercepts are the points where the graph crosses the x-axis, meaning $f (x) = 0$. By observing the graph, we identify three distinct points where the curve intersects the x-axis:\n* $x = -1$\n* $x = 0$\n* $x = 1$\n\n**2. Formulate the polynomial:**\nIf a polynomial has roots at $x = a$, $x = b$, and $x = c$, it can be expressed in factored form as:\n$f (x) = k (x - a)(x - b)(x - c)$\nSubstituting our roots $(-1, 0, 1)$ into this form:\n$f (x) = k (x - (-1))(x - 0)(x - 1)$\n$f (x) = k (x + 1)(x)(x - 1)$\n\n**3. Simplify the expression:**\nUsing the difference of squares identity, $(x + 1)(x - 1) = x^2 - 1$. Thus:\n$f (x) = k (x)(x^2 - 1)$\n$f (x) = k (x^3 - x)$\n\n**4. Determine the leading coefficient ($k$):**\nThe graph shows that as $x \\to \\infty$, $f (x) \\to \\infty$, and as $x \\to -\\infty$, $f (x) \\to -\\infty$. This indicates a positive leading coefficient. Assuming $k = 1$, we get:\n$f (x) = x^3 - x$\n\n### Conclusion\nComparing our derived function $f (x) = x^3 - x$ with the given options:\n* Option A ($x^3 + x + 1$) does not have these roots.\n* Option B ($x^3 - x + 1$) does not have these roots.\n* **Option C ($x^3 - x$)** matches our derived function perfectly, as it satisfies $f(-1) = 0$, $f (0) = 0$, and $f (1) = 0$. Therefore, **Choice C** is the correct represent at i on of the graph.",
          "grade_id": "grade-12-natural",
          "subject_id": "subj-math",
          "topic_name": "Relations & Functions",
          "section_instruction": "Answer question 17 based on Unit 1: Relations and Functions standards.",
          "instruction_category": "Relations & Functions",
          "difficulty": "Easy",
          "extraction_method": "high_fidelity_pdf_reparse",
          "extraction_confidence": 1,
          "needs_review": false,
          "is_ai_generated": false,
          "exam_title": "2018 E.C. Mathematics EUEE Exam",
