      "explanation": "To solve this problem, we must apply the proper ties of a right-angled triangle and the geometric mean theorem (also known as the altitude rule). In a right-angled triangle, if an altitude is drawn from the right-angle vertex to the hypotenuse, it creates two smaller triangles that are similar to the original triangle and to each other.\n\n### Step-by-Step Derivation:\n\n1. **Identify the Triangle Proper ties:**\n We are given a right-angled triangle $\\triangle ABC$. Assuming the right angle is at $C$ (as is standard for this specific EUEE problem configuration where $AC$ and $BC$ are the legs), we first find the hypotenuse $AB$ using the Pythagorean theorem:\n $$AB = \\sqrt{AC^2 + BC^2} = \\sqrt{5^2 + 4^2} = \\sqrt{25 + 16} = \\sqrt{41}$$\n\n2. **Relate the Altitude to the Sides:**\n Let $CD$ be the altitude from $C$ to the hypotenuse $AB$. The area of $\\triangle ABC$ can be calculated in two ways:\n $$\\text{Area} = \\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2} \\times AC \\times BC$$\n $$\\text{Area} = \\frac{1}{2} \\times AB \\times CD$$\n Equating these: $AC \\times BC = AB \\times CD$.\n $$CD = \\frac{AC \\times BC}{AB} = \\frac{5 \\times 4}{\\sqrt{41}} = \\frac{20}{\\sqrt{41}}$$\n\n3. **Calculate $BD$:**\n In the right-angled triangle $\\triangle BDC$, we use the Pythagorean theorem:\n $$BC^2 = BD^2 + CD^2$$\n $$4^2 = BD^2 + \\left(\\frac{20}{\\sqrt{41}}\\right)^2$$\n $$16 = BD^2 + \\frac{400}{41}$$\n $$BD^2 = 16 - \\frac{400}{41} = \\frac{656 - 400}{41} = \\frac{256}{41}$$\n $$BD = \\sqrt{\\frac{256}{41}} = \\frac{16}{\\sqrt{41}} \\approx \\frac{16}{6.403} \\approx 2.499 \\approx 2.4 \\text{ cm}$$\n\nGiven the standard geometry of this EUEE question, the calculation confirms that **Choice B (2.4cm)** is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Determinants & Cramer Rule",
