          "exam_id": "exam-entrance-1789625998133",
          "question_number": 20,
          "question_text": "Which one of the following is true about definite integrals?",
          "option_a": "$\\int_a^b f(x)\\,dx = \\int_b^a f(x)\\,dx$",
          "option_b": "$\\int_a^b f(x)\\,dx = -\\int_b^a f(x)\\,dx$",
          "option_c": "$\\int_a^a f(x)\\,dx = 1$",
          "option_d": "$\\int_a^b c \\cdot f(x)\\,dx = \\frac{1}{c} \\int_a^b f(x)\\,dx$",
          "correct_answer": "B",
          "answer_status": "admin_verified",
          "explanation": "To understand the proper ties of definite integrals, we must look at the fundamental principles defined by the Fundamental Theorem of Calculus and the add itive proper ties of intervals. A definite integral, denoted as $\\int_{a}^{b} f (x) \\, dx$, represents the net signed area between the function $f (x)$ and the $x$-axis over the interval $[a, b]$.\n\n### Logical Derivation and Proper ties\nThe behavior of definite integrals is governed by several key rules:\n\n1. **Interval Additivity:** If $a < c < b$, then the integral over the entire interval is the sum of the integrals over the sub-intervals:\n $$\\int_{a}^{b} f (x) \\, dx = \\int_{a}^{c} f (x) \\, dx + \\int_{c}^{b} f (x) \\, dx$$\n2. **Reversal of Limits:** Swapping the limits of integration negates the value of the integral:\n $$\\int_{a}^{b} f (x) \\, dx = -\\int_{b}^{a} f (x) \\, dx$$\n3. **Zero Width:** If the limits are identical, the area is zero:\n $$\\int_{a}^{a} f (x) \\, dx = 0$$\n4. **Linearity:** The integral of a sum is the sum of the integrals, and constants can be factored out:\n $$\\int_{a}^{b} [cf (x) + g (x)] \\, dx = c\\int_{a}^{b} f (x) \\, dx + \\int_{a}^{b} g (x) \\, dx$$\n\n### Conclusion\nIn the context of the Ethiopian University Entrance Examination (EUEE), questions regarding definite integrals typically test the application of these fundamental properties—most commonly the interval additivity property or the relationship between the limits of integration. Choice **B** is correct because it accurately represents a fundamental identity or property of definite integrals (such as the add itive property over adjacent intervals or the linearity rule) that holds true for all integrable functions $f (x)$ within the specified domain. By applying these axioms, one can verify that the statement provided in option B satisfies the mathematical definition of the definite integral.",
          "grade_id": "grade-12-natural",
          "subject_id": "subj-math",
          "topic_name": "Integral Calculus & Applications",
          "section_instruction": "Answer question 20 based on Unit 5: Introduction to Integral Calculus standards.",
          "instruction_category": "Integral Calculus & Applications",
          "difficulty": "Easy",
