      "id": "q-exam-entrance-1789625998133-21",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 21,
      "question_text": "Which of the following statements defines a circle?",
      "option_a": "It is the set of points in a plane formed by the intersection of two secants in the plane.",
      "option_b": "It is the set of points in a space formed by the intersection of two secants in the space.",
      "option_c": "It is the set of points in a space each of which is equidistant from a fixed point in the space.",
      "option_d": "It is the set of points in a plane each of which is equidistant from a fixed point in the plane.",
      "correct_answer": "D",
      "answer_status": "admin_verified",
      "explanation": "### Explanation of the Definition of a Circle\n\nA circle is fundamentally defined in geometry as the locus of points that maintain a constant distance from a fixed central point within a two-dimensional surface.\n\n#### Logical Reasoning Process:\n\n1. **Defining the Locus:** A \" locus \" is a set of points that satisfy a specific condition. For a circle, that condition is a constant distance ($r$), known as the radius, from a fixed point ($h, k$), known as the center.\n2. **Dimensionality:** A circle is a planar figure. This means it exists entirely within a two-dimensional plane. If we were to define a set of points equidistant from a fixed point in three-dimensional space, we would be describing a **sphere**, not a circle. This immediately eliminates options B and C.\n3. **Analyzing the Geometric Construction:**\n * **Options A and B:** These describe intersections of lines (secants). The intersection of two secants typically results in a single point or a line, not the continuous, closed curve that defines a circle.\n * **Option D:** This statement specifies that the points must lie in a **plane** and must be **equidistant** from a fixed point (the center). Mathematically, if the center is $(h, k)$ and any point on the circle is $(x, y)$, the distance formula gives:\n $$\\sqrt{(x - h)^2 + (y - k)^2} = r$$\n Squaring both sides yields the standard equation of a circle:\n $$(x - h)^2 + (y - k)^2 = r^2$$\n\n#### Conclusion:\nBecause a circle is strictly a two-dimensional object defined by a constant radius from a center point, only **Option D** accurately captures the geometric definition. It correctly i dent if ies both the planar nature of the figure and the equidistant property required to form the boundary of the circle.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Vectors in 2D & 3D Space",
      "section_instruction": "Answer question 21 based on Unit 5: Vectors standards.",
      "instruction_category": "Vectors in 2D & 3D Space",
