          "id": "q-exam-entrance-1789625998133-22",
          "exam_id": "exam-entrance-1789625998133",
          "question_number": 22,
          "question_text": "What is the transpose of the matrix $A = \\begin{pmatrix} 1 & -2 \\\\ 3 & 4 \\end{pmatrix}$?",
          "option_a": "$\\begin{pmatrix} -1 & 2 \\\\ -3 & -4 \\end{pmatrix}$",
          "option_b": "$\\begin{pmatrix} 1 & 3 \\\\ -2 & 4 \\end{pmatrix}$",
          "option_c": "$\\begin{pmatrix} 4 & -2 \\\\ 3 & 1 \\end{pmatrix}$",
          "option_d": "$\\begin{pmatrix} 4 & 2 \\\\ -3 & 1 \\end{pmatrix}$",
          "correct_answer": "B",
          "answer_status": "admin_verified",
          "explanation": "To find the transpose of a matrix, we apply a fundamental operation in linear algebra where the rows and columns of the original matrix are interchanged. Specifically, if we have a matrix $A$ of size $m \\times n$, its transpose, denoted as $A^T$, is an $n \\times m$ matrix where the element at the $i$-th row and $j$-th column of $A$ moves to the $j$-th row and $i$-th column of $A^T$. Mathematically, this is defined as:\n$$(A^T)_{ij} = A_{ji}$$\n\n### Step-by-Step Derivation:\n\n1. **Identify the original matrix dimensions:** Let the given matrix be $A$. Observe the elements in each row of $A$.\n2. **Convert rows to columns:** Take the first row of matrix $A$ and rewrite it as the first column of the new matrix $A^T$.\n3. **Repeat for all rows:** Take the second row of matrix $A$ and rewrite it as the second column of $A^T$. Continue this process until every row of the original matrix has been transformed into a corresponding column in the transpose matrix.\n4. **Verify the result:** Ensure that the dimensions have been swapped (if the original was $m \\times n$, the transpose must be $n \\times m$) and that every element $a_{ij}$ is now located at position $(j, i)$.\n\n### Conclusion:\nBy systematic ally swapping the rows and columns of the given matrix, we generate the transpose. Upon comparing the resulting matrix with the provided options, we find that the arrangement of elements matches the matrix presented in **Option B**. Therefore, Option B is the correct transpose of the given matrix.",
          "grade_id": "grade-12-natural",
          "subject_id": "subj-math",
          "topic_name": "Matrices & Systems of Linear Equations",
          "section_instruction": "Answer question 22 based on Unit 3: Matrices standards.",
          "instruction_category": "Matrices & Systems of Linear Equations",
          "difficulty": "Easy",
