      "id": "q-exam-entrance-1789625998133-23",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 23,
      "question_text": "Which one of the following sets is the domain of the rational function",
      "option_a": "R\\{1}",
      "option_b": "R\\{−1,1}",
      "option_c": "R\\{−3,1}",
      "option_d": "R\\{−1,1,−3}\n\n2018 Maths",
      "correct_answer": "B",
      "answer_status": "admin_verified",
      "explanation": "To determine the domain of a rational function, we must identify all real numbers for which the function is defined. A rational function $f (x) = \\frac{P (x)}{Q (x)}$ is undefined whenever the denominator $Q (x)$ equals zero, as division by zero is undefined in mathematics. Therefore, the domain is the set of all real numbers $\\mathbb{R}$ excluding the roots of the denominator. Although the specific function expression was omitted in your prompt, based on the provided options (specifically the exclusion of $\\{-1, 1\\}$), we can infer the denominator is $x^2 - 1$.\n\n### Step-by-Step Derivation:\n\n1. **Identify the Denominator:** For a rational function to be defined, the denominator must not be zero. Let the denominator be $D (x) = x^2 - 1$.\n2. **Set the Denominator to Zero:** To find the values that must be excluded from the domain, solve the equation:\n $$x^2 - 1 = 0$$\n3. **Factor the Expression:** Use the difference of squares formula, $a^2 - b^2 = (a - b)(a + b)$:\n $$(x - 1)(x + 1) = 0$$\n4. **Solve for $x$:**\n * $x - 1 = 0 \\implies x = 1$\n * $x + 1 = 0 \\implies x = -1$\n5. **Define the Domain:** The function is defined for all real numbers except $x = 1$ and $x = -1$. In set not at i on, this is written as $\\mathbb{R} \\setminus \\{-1, 1\\}$.\n\n### Conclusion:\nSince the values $1$ and $-1$ make the denominator zero, they must be excluded from the set of real numbers. This matches **Option B: $\\mathbb{R} \\setminus \\{-1, 1\\}$**, which is the correct domain for the function.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Relations & Functions",
      "section_instruction": "Answer question 23 based on Unit 1: Relations and Functions standards.",
      "instruction_category": "Relations & Functions",
      "difficulty": "Easy",
