      "id": "q-exam-entrance-1789625998133-28",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 28,
      "question_text": "Let A={x∈R: x3−x=0}and B={x∈Z:−1≤x<3}. What is the relative complement of B with respect\nto A (i.e., A∖B)?",
      "option_a": "{2}",
      "option_b": "{0,1}",
      "option_c": "∅",
      "option_d": "{−1,0,1}",
      "correct_answer": "C",
      "answer_status": "admin_verified",
      "explanation": "To find the relative complement of set $B$ with respect to set $A$ (denoted as $A \\setminus B$), we must identify all elements that are in set $A$ but are not in set $B$.\n\n### Step 1: Determine the elements of set $A$\nSet $A$ is defined as $\\{x \\in \\mathbb{R} : x^3 - x = 0\\}$. We solve the equation by factoring:\n$$x^3 - x = 0$$\n$$x (x^2 - 1) = 0$$\n$$x (x - 1)(x + 1) = 0$$\nThe solutions are $x = 0$, $x = 1$, and $x = -1$. Since all these values are real numbers, we have:\n$$A = \\{-1, 0, 1\\}$$\n\n### Step 2: Determine the elements of set $B$\nSet $B$ is defined as $\\{x \\in \\mathbb{Z} : -1 \\le x < 3\\}$. This set includes all integers starting from $-1$ up to, but not including, $3$:\n$$B = \\{-1, 0, 1, 2\\}$$\n\n### Step 3: Calculate the relative complement $A \\setminus B$\nThe relative complement $A \\setminus B$ consists of all elements that belong to $A$ but do not belong to $B$. We compare the two sets:\n* $-1$ is in $A$ and is also in $B$. (Exclude)\n* $0$ is in $A$ and is also in $B$. (Exclude)\n* $1$ is in $A$ and is also in $B$. (Exclude) Since every element of $A$ is also contained within $B$, there are no elements left in $A$ after removing those found in $B$. Therefore:\n$$A \\setminus B = \\empty set$$\n\n### Conclusion\nBecause $A \\subseteq B$, the set $A \\setminus B$ results in the empty set. This matches **Option C**.",
