      "id": "q-exam-entrance-1789625998133-31",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 31,
      "question_text": "Which statement is true about the graphs of the exponential functions f (x)=ax\nf and g (x)=(1/a) x where a>1?",
      "option_a": "They are reflect i ons of each other across the x-axis.",
      "option_b": "They are reflect i ons of each other across the y-axis.",
      "option_c": "They never intersect each other.",
      "option_d": "Both functions are monotonically increasing.",
      "correct_answer": "B",
      "answer_status": "admin_verified",
      "explanation": "To understand the relationship between the functions $f (x) = a^x$ and $g (x) = (\\frac{1}{a})^x$ where $a > 1$, we must look at the proper ties of exponential transform at i ons.\n\n### Conceptual Explanation\nIn coordinate geometry, a reflect i on of a function $f (x)$ across the $y$-axis is defined by the transform at i on $f(-x)$. When we replace the input $x$ with $-x$ in a function, the graph flips horizontally over the vertical axis.\n\n### Step-by-Step Derivation\n1. **Analyze the given functions:**\n We are given $f (x) = a^x$. We are given $g (x) = (\\frac{1}{a})^x$.\n\n2. **Apply exponent laws:**\n Recall that $\\frac{1}{a}$ can be written as $a^{-1}$. Therefore, we can rewrite $g (x)$ as:\n $g (x) = (a^{-1})^x$\n Using the power of a power rule $(a^m)^n = a^{m \\cdot n}$, we get:\n $g (x) = a^{-x}$\n\n3. **Compare $f (x)$ and $g (x)$:**\n We now see that $g (x) = f(-x)$. By the definition of function transform at i ons, replacing $x$ with $-x$ results in a reflect i on across the $y$-axis.\n\n4. **Evaluate the options:**\n * **A:** Reflect i on across the $x$-axis would be $-f (x) = -a^x$, which is not $g (x)$.\n * **B:** As derived, $g (x) = f(-x)$, which is the definition of a reflect i on across the $y$-axis.\n * **C:** Both functions pass through the point $(0, 1)$ because $a^0 = 1$ and $(\\frac{1}{a})^0 = 1$. Thus, they intersect at the $y$-intercept.\n * **D:** Since $a > 1$, $f (x)$ is increasing, but $g (x) = (\\frac{1}{a})^x$ is decreasing because the base is between $0$ and $1$.\n\n### Conclusion\nBecause $g (x) = f(-x)$, the graph of $g (x)$ is the mirror image of $f (x)$ reflected across the $y$-axis. Therefore, **Option B** is the correct statement.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Relations & Functions",
      "section_instruction": "Answer question 31 based on Unit 1: Relations and Functions standards.",
      "instruction_category": "Relations & Functions",
