      "id": "q-exam-entrance-1789625998133-33",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 33,
      "question_text": "Which one of the following numbers is an irrational number?",
      "option_a": "3.14159 (term inating)",
      "option_b": "C. 22/7\nD. π",
      "option_c": "22/7",
      "option_d": "π",
      "correct_answer": "D",
      "answer_status": "admin_verified",
      "explanation": "To understand why $\\pi$ is an irrational number, we must first define the set of rational numbers. A number is **rational** if it can be expressed as a fraction $\\frac{p}{q}$, where $p$ and $q$ are integers and $q \\neq 0$. Equivalently, a rational number has a decimal represent at i on that either term inates (ends) or repeats in a periodic pattern. An **irrational number** is any real number that cannot be expressed as such a fraction; its decimal expansion is non-terminating and non-repeating.\n\n### Step-by-Step Reasoning:\n\n1. **Analyze Option A ($3.14159$):** This is a term inating decimal. Any term inating decimal can be written as a fraction (e.g., $3.14159 = \\frac{314159}{100000}$). Therefore, it is a rational number.\n2. **Analyze Option C ($\\frac{22}{7}$):** By definition, this is a ratio of two integers ($22$ and $7$). Since it is already in the form $\\frac{p}{q}$, it is a rational number. Note that while $\\frac{22}{7}$ is a common approximation for $\\pi$, it is not equal to $\\pi$.\n3. **Analyze Option D ($\\pi$):** The number $\\pi$ is defined as the ratio of a circle's circumference to its diameter. Mathematical proofs (first established by Johann Lambert in 1761) demonstrate that $\\pi$ cannot be expressed as a fraction of two integers. Its decimal expansion, $3.14159265...$, continues infinitely without ever settling into a repeating cycle.\n\n### Conclusion:\nBecause $\\pi$ is a non-terminating, non-repeating decimal that cannot be expressed as a ratio of two integers, it satisfies the definition of an irrational number. Thus, **Choice D** is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Statistics & Grouped Data",
      "section_instruction": "Answer question 33 based on Unit 7: Statistics standards.",
      "instruction_category": "Statistics & Grouped Data",
      "difficulty": "Medium",
