          "id": "q-exam-entrance-1789625998133-34",
          "exam_id": "exam-entrance-1789625998133",
          "question_number": 34,
          "question_text": "What is the area of the parallelogram spanned by the vectors $\\mathbf{u} = \\mathbf{i} - 2\\mathbf{j} + \\mathbf{k}$ and $\\mathbf{v} = 2\\mathbf{i} + 2\\mathbf{j} - \\mathbf{k}$?",
          "option_a": "$\\sqrt{35}$",
          "option_b": "$3\\sqrt{5}$",
          "option_c": "$5\\sqrt{3}$",
          "option_d": "$6\\sqrt{2}$",
          "correct_answer": "B",
          "answer_status": "admin_verified",
          "explanation": "To find the area of a parallelogram spanned by two vectors $\\mathbf{u}$ and $\\mathbf{v}$ in three-dimensional space, we use the geometric property that the area is equal to the magnitude of their cross product:\n$$\\text{Area} = \\|\\mathbf{u} \\times \\mathbf{v}\\|$$\n\n### Step-by-Step Derivation:\n\n**1. Represent the vectors in component form:**\nGiven $\\mathbf{u} = \\mathbf{i} - 2\\mathbf{j} + \\mathbf{k}$ and $\\mathbf{v} = 2\\mathbf{i} + 2\\mathbf{j} - \\mathbf{k}$, we write them as:\n$\\mathbf{u} = \\langle 1, -2, 1 \\rangle$\n$\\mathbf{v} = \\langle 2, 2, -1 \\rangle$\n\n**2. Calculate the cross product $\\mathbf{u} \\times \\mathbf{v}$:**\nThe cross product is calculated using the determinant of a $3 \\times 3$ matrix:\n$$\\mathbf{u} \\times \\mathbf{v} = \\begin{vmatrix} \\mathbf{i} & \\mathbf{j} & \\mathbf{k} \\\\ 1 & -2 & 1 \\\\ 2 & 2 & -1 \\end{vmatrix}$$\nExpanding along the first row:\n$= \\mathbf{i}((-2)(-1) - (1)(2)) - \\mathbf{j}((1)(-1) - (1)(2)) + \\mathbf{k}((1)(2) - (-2)(2))$\n$= \\mathbf{i}(2 - 2) - \\mathbf{j}(-1 - 2) + \\mathbf{k}(2 + 4)$\n$= 0\\mathbf{i} + 3\\mathbf{j} + 6\\mathbf{k} = \\langle 0, 3, 6 \\rangle$\n\n**3. Calculate the magnitude of the resulting vector:**\nThe area is the magnitude of $\\langle 0, 3, 6 \\rangle$:\n$$\\text{Area} = \\sqrt{0^2 + 3^2 + 6^2} = \\sqrt{0 + 9 + 36} = \\sqrt{45}$$\nSimplifying the radical:\n$$\\sqrt{45} = \\sqrt{9 \\times 5} = 3\\sqrt{5}$$\n\n### Conclusion:\nThe area of the parallelogram is $3\\sqrt{5}$ square units. Assuming Option B corresponds to the value $3\\sqrt{5}$, this confirms that **Choice B** is the correct answer.",
          "grade_id": "grade-12-natural",
          "subject_id": "subj-math",
          "topic_name": "Vectors in 2D & 3D Space",
          "section_instruction": "Answer question 34 based on Unit 5: Vectors standards.",
          "instruction_category": "Vectors in 2D & 3D Space",
