      "id": "q-exam-entrance-1789625998133-35",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 35,
      "question_text": "What is the fundamental period of the function f (x)=sin (x)?",
      "option_a": "π/2",
      "option_b": "π",
      "option_c": "2π",
      "option_d": "4π",
      "correct_answer": "C",
      "answer_status": "admin_verified",
      "explanation": "### Explanation of the Fundamental Period of $f (x) = \\sin (x)$\n\nThe **fundamental period** of a periodic function $f (x)$ is defined as the smallest positive constant $T$ such that $f (x + T) = f (x)$ for all $x$ in the domain of the function. For trigonometric functions, this represents the length of the shortest interval over which the function completes one full cycle before repeating its values.\n\n#### Step-by-Step Derivation:\n\n1. **Definition of Period i city:** We seek the smallest positive value $T$ that satisfies the equation:\n $$\\sin (x + T) = \\sin (x)$$\n\n2. **Using Trigonometric I dent i ties:** Recall the unit circle definition of the sine function. The sine function represents the $y$-coordinate of a point on the unit circle. A point on the unit circle returns to its original position after a full rotation of $2\\pi$ radians. Therefore, we know that:\n $$\\sin (x + 2\\pi) = \\sin (x)$$\n\n3. **Testing Smaller Values:** We must verify if there exists a smaller positive value $T < 2\\pi$ that satisfies the condition. \n * If we test $T = \\pi$, we know from trigonometric i dent i ties that $\\sin (x + \\pi) = -\\sin (x)$. Since $-\\sin (x) \\neq \\sin (x)$ for all $x$, $\\pi$ is not the period.\n * If we test $T = \\frac{\\pi}{2}$, we know that $\\sin (x + \\frac{\\pi}{2}) = \\cos (x)$. Since $\\cos (x) \\neq \\sin (x)$ for all $x$, $\\frac{\\pi}{2}$ is not the period.\n\n4. **Conclusion:** Since $2\\pi$ is the smallest positive value for which the sine function repeats its cycle, it is defined as the fundamental period.\n\n**Final Confirm at i on:**\nBased on the derivation above, the fundamental period of $f (x) = \\sin (x)$ is $2\\pi$. Therefore, **Choice C** is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Statistics & Grouped Data",
