      "id": "q-exam-entrance-1789625998133-36",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 36,
      "question_text": "What is the simplified form of the expression\n\n2018 Maths",
      "option_a": "16",
      "option_b": "-16",
      "option_c": "8",
      "option_d": "-8",
      "correct_answer": "B",
      "answer_status": "admin_verified",
      "explanation": "To simplify the expression $\\frac{2^{2020} - 2^{2018}}{2^{2018} - 2^{2016}}$, we utilize the proper ties of exponents, specifically the rule $a^{m+n} = a^m \\cdot a^n$. The goal is to factor out the smallest power of 2 from both the numerator and the denominator to cancel common terms.\n\n### Step-by-Step Derivation:\n\n**Step 1: Factor the numerator.**\nIn the numerator $2^{2020} - 2^{2018}$, the smallest power is $2^{2018}$. We can rewrite $2^{2020}$ as $2^{2018} \\cdot 2^2$.\n$$2^{2020} - 2^{2018} = 2^{2018}(2^2 - 1) = 2^{2018}(4 - 1) = 3 \\cdot 2^{2018}$$\n\n**Step 2: Factor the denominator.**\nIn the denominator $2^{2018} - 2^{2016}$, the smallest power is $2^{2016}$. We can rewrite $2^{2018}$ as $2^{2016} \\cdot 2^2$.\n$$2^{2018} - 2^{2016} = 2^{2016}(2^2 - 1) = 2^{2016}(4 - 1) = 3 \\cdot 2^{2016}$$\n\n**Step 3: Simplify the fraction.**\nNow, substitute the factored forms back into the original expression:\n$$\\frac{3 \\cdot 2^{2018}}{3 \\cdot 2^{2016}}$$\nThe constant $3$ cancels out, leaving:\n$$\\frac{2^{2018}}{2^{2016}}$$\n\n**Step 4: Apply the quotient rule for exponents.**\nUsing the rule $\\frac{a^m}{a^n} = a^{m-n}$:\n$$2^{2018-2016} = 2^2 = 4$$\n\n***Correct i on Note:*** Based on the standard algebraic simplification of the provided expression, the result is $4$. However, if the expression intended to involve a negative sign or a specific structure leading to $-16$, please verify the original problem's signs. Given the provided options and the requirement to confirm **Choice B (-16)**, it implies a potential typo in the source question's signs (e.g., if the denominator were reversed). Following the mathematical logic of the expression provided, the result is $4$; if the answer must be $-16$, the expression likely contained a negative factor or inverted subtraction.",
