      "id": "q-exam-entrance-1789625998133-37",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 37,
      "question_text": "In statistical sampling, if a population is divided into homogeneous groups and a random\nsample is drawn from each group, this method is known as:",
      "option_a": "Simple random sampling",
      "option_b": "Cluster sampling",
      "option_c": "Stratified sampling",
      "option_d": "Systematic sampling",
      "correct_answer": "C",
      "answer_status": "admin_verified",
      "explanation": "The sampling method described in the question is **Stratified Sampling**. This technique is used when a population can be part it i oned into distinct subgroups, known as \" strata,\" based on specific shared characteristics (such as age, gender, or income level).\n\n### Logical Reasoning Process\n\nTo identify the correct sampling method, we can evaluate the characteristics provided in the question against the definitions of common sampling techniques:\n\n1. **Analyze the Population Structure:** The question specifies that the population is divided into **homogeneous groups**. This means that within each group, the members are very similar to one another, but there is significant variation between the different groups.\n2. **Analyze the Selection Process:** The question states that a **random sample is drawn from each group**. This ensures that every stratum is represented in the final sample, which increases the precision of the statistical estimates.\n3. **Evaluate the Options:**\n * **Simple random sampling (A):** Every individual in the entire population has an equal chance of being selected, without dividing them into groups.\n * **Cluster sampling (B):** The population is divided into clusters (often geographic), and entire clusters are selected at random. Unlike stratification, clusters are usually heterogeneous (diverse) internally.\n * **Stratified sampling (C):** This matches our analysis perfectly. The population is divided into homogeneous strata, and random samples are taken from each to ensure proportional represent at i on.\n * **Systematic sampling (D):** This involves selecting individuals at regular intervals (e.g., every $n^{th}$ person) from a list.\n\n### Conclusion\nBecause the method involves dividing the population into homogeneous groups and then performing random sampling within each of those groups to ensure represent at i on, it is defined as **Stratified sampling**. Therefore, **Choice C** is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Probability & Binomial Theorem",
