          "id": "q-exam-entrance-1789625998133-38",
          "exam_id": "exam-entrance-1789625998133",
          "question_number": 38,
          "question_text": "A mathematics exam contains 10 multiple-choice questions and 3 short-answer questions. According to the multiplication principle, how many ways can a student select exactly one multiple-choice question and exactly one short-answer question to solve first?",
          "option_a": "13",
          "option_b": "30",
          "option_c": "10",
          "option_d": "3",
          "correct_answer": "B",
          "answer_status": "admin_verified",
          "explanation": "### Explanation: The Fundamental Counting Principle\n\nTo solve this problem, we use the **Fundamental Counting Principle** (also known as the Multiplication Principle). This principle states that if one task can be performed in $m$ ways and a second independent task can be performed in $n$ ways, then the total number of ways to perform both tasks in sequence is $m \\times n$.\n\n#### Step-by-Step Derivation:\n\n1. **Identify the tasks:**\n * **Task 1:** Selecting one multiple-choice question to solve first.\n * **Task 2:** Selecting one short-answer question to solve first.\n\n2. **Determine the number of options for each task:**\n * There are $10$ multiple-choice questions available. Therefore, the number of ways to choose one multiple-choice question is $m = 10$.\n * There are $3$ short-answer questions available. Therefore, the number of ways to choose one short-answer question is $n = 3$.\n\n3. **Apply the Multiplication Principle:**\n Since the student must select one from each category, we multiply the number of choices for each task:\n $$\\text{Total ways} = (\\text{Number of multiple-choice options}) \\times (\\text{Number of short-answer options})$$\n $$\\text{Total ways} = 10 \\times 3 = 30$$\n\n#### Conclusion:\nBy multiplying the number of available choices for each independent task, we find there are $30$ distinct combinations of one multiple-choice question and one short-answer question. Therefore, **Option B** is the correct answer.",
          "grade_id": "grade-12-natural",
          "subject_id": "subj-math",
          "topic_name": "Probability & Binomial Theorem",
          "section_instruction": "Answer question 38 based on Unit 8: Probability standards.",
