      "id": "q-exam-entrance-1789625998133-39",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 39,
      "question_text": "A translation vector maps the origin (0,0) to the point (−2,4). Under this same translation, what\nis the image of the point (3,1)?",
      "option_a": "(5,−3)",
      "option_b": "(1,5)",
      "option_c": "(−6,4)",
      "option_d": "(−5,3)",
      "correct_answer": "B",
      "answer_status": "admin_verified",
      "explanation": "### Explanation of Translation in a Coordinate Plane\n\nA **translation** is a geometric transform at i on that shifts every point in a plane by the same distance in the same direction. This shift is defined by a translation vector, denoted as $\\vec{v} = \\begin{pmatrix} a \\\\ b \\end{pmatrix}$. When a point $(x, y)$ is translated by this vector, its image $(x', y')$ is found by adding the components of the vector to the original coordinates:\n$x' = x + a$\n$y' = y + b$\n\n#### Step-by-Step Derivation:\n\n**Step 1: Determine the translation vector.**\nWe are given that the origin $(0, 0)$ is mapped to the point $(-2, 4)$. Let the translation vector be $\\vec{v} = \\begin{pmatrix} a \\\\ b \\end{pmatrix}$. Using the translation formula:\n$0 + a = -2 \\implies a = -2$\n$0 + b = 4 \\implies b = 4$\nThus, the translation vector is $\\vec{v} = \\begin{pmatrix} -2 \\\\ 4 \\end{pmatrix}$.\n\n**Step 2: Apply the translation to the point $(3, 1)$.**\nTo find the image of the point $(3, 1)$, we add the translation vector $\\begin{pmatrix} -2 \\\\ 4 \\end{pmatrix}$ to its coordinates:\n$x' = 3 + (-2) = 1$\n$y' = 1 + 4 = 5$\n\n**Conclusion:**\nThe image of the point $(3, 1)$ under this translation is $(1, 5)$. Comparing this result to the given options, we find that it matches **Option B**.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Transformations of the Plane",
      "section_instruction": "Answer question 39 based on Unit 6: Transform at i ons of the Plane standards.",
      "instruction_category": "Transformations of the Plane",
      "difficulty": "Medium",
