      "id": "q-exam-entrance-1789625998133-40",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 40,
      "question_text": "If the initial point of a vector is A (2,−1,4) and the terminal point is B (4,3,2), what is the position\nvector AB ?",
      "option_a": "⟨−2,−4,2⟩",
      "option_b": "⟨6,2,6⟩",
      "option_c": "⟨2,4,−2⟩",
      "option_d": "⟨8,−3,8⟩",
      "correct_answer": "C",
      "answer_status": "admin_verified",
      "explanation": "To find the position vector of a directed line segment $\\vec{AB}$ given its initial point $A$ and terminal point $B$, we use the fundamental principle of vector subtraction.\n\n### Concept\nA position vector represents the displacement from the origin to a point. When given two points $A (x_1, y_1, z_1)$ and $B (x_2, y_2, z_2)$, the vector $\\vec{AB}$ is defined as the difference between the coordinates of the terminal point and the initial point:\n$$\\vec{AB} = \\vec{B} - \\vec{A} = \\langle x_2 - x_1, y_2 - y_1, z_2 - z_1 \\rangle$$\n\n### Step-by-Step Derivation\nGiven the points:\n* Initial point $A = (2, -1, 4)$\n* Terminal point $B = (4, 3, 2)$\n\n**Step 1: Identify the components.**\n* $x_1 = 2, y_1 = -1, z_1 = 4$\n* $x_2 = 4, y_2 = 3, z_2 = 2$\n\n**Step 2: Apply the subtraction formula.**\nSubtract the coordinates of $A$ from the coordinates of $B$:\n$$\\vec{AB} = \\langle 4 - 2, \\quad 3 - (-1), \\quad 2 - 4 \\rangle$$\n\n**Step 3: Perform the arithmetic.**\n* $x$-component: $4 - 2 = 2$\n* $y$-component: $3 + 1 = 4$\n* $z$-component: $2 - 4 = -2$\n\nThus, the resulting vector is $\\vec{AB} = \\langle 2, 4, -2 \\rangle$.\n\n### Conclusion\nComparing our result to the given options, $\\langle 2, 4, -2 \\rangle$ matches **Option C**. This confirms that the vector representing the displacement from $A$ to $B$ is indeed $\\langle 2, 4, -2 \\rangle$.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Vectors in 2D & 3D Space",
      "section_instruction": "Answer question 40 based on Unit 5: Vectors standards.",
      "instruction_category": "Vectors in 2D & 3D Space",
      "difficulty": "Medium",
      "extraction_method": "high_fidelity_pdf_reparse",
