      "id": "q-exam-entrance-1789625998133-41",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 41,
      "question_text": "Let vector u have an initial point at (1,2) and a terminal point at (−3,6). What are the\ncomponents of the vector −1/2u ?",
      "option_a": "⟨2,−2⟩",
      "option_b": "⟨−2,2⟩",
      "option_c": "⟨4,−4⟩\n\n2018 Maths",
      "option_d": "⟨1,−1⟩",
      "correct_answer": "A",
      "answer_status": "admin_verified",
      "explanation": "To find the components of a vector given its initial and terminal points, we use the displacement formula. If a vector $\\vec{u}$ has an initial point $P_1 (x_1, y_1)$ and a terminal point $P_2 (x_2, y_2)$, its components are given by $\\vec{u} = \\langle x_2 - x_1, y_2 - y_1 \\rangle$.\n\n### Step-by-Step Derivation:\n\n**Step 1: Find the components of vector $\\vec{u}$.**\nGiven the initial point $(1, 2)$ and the terminal point $(-3, 6)$:\n$$\\vec{u} = \\langle -3 - 1, 6 - 2 \\rangle$$\n$$\\vec{u} = \\langle -4, 4 \\rangle$$\n\n**Step 2: Calculate $-\\frac{1}{2}\\vec{u}$.**\nTo multiply a vector by a scalar, we multiply each component of the vector by that scalar:\n$$-\\frac{1}{2}\\vec{u} = -\\frac{1}{2} \\langle -4, 4 \\rangle$$\n$$-\\frac{1}{2}\\vec{u} = \\left\\langle -\\frac{1}{2} \\cdot (-4), -\\frac{1}{2} \\cdot 4 \\right\\rangle$$\n\n**Step 3: Simplify the components.**\n$$-\\frac{1}{2} \\cdot (-4) = 2$$\n$$-\\frac{1}{2} \\cdot 4 = -2$$\nThus, $-\\frac{1}{2}\\vec{u} = \\langle 2, -2 \\rangle$.\n\n### Conclusion:\nBy calculating the displacement vector $\\vec{u}$ and applying scalar multiplication, we arrive at the components $\\langle 2, -2 \\rangle$. This matches **Option A**, which is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Vectors in 2D & 3D Space",
