      "id": "q-exam-entrance-1789625998133-42",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 42,
      "question_text": "Consider the rational function f (x)=x2−4/x−2. The domain of f is the set of all real numbers\nEXCEPT:",
      "option_a": "-2",
      "option_b": "2",
      "option_c": "0",
      "option_d": "The domain is all real numbers.",
      "correct_answer": "B",
      "answer_status": "admin_verified",
      "explanation": "### Explanation of the Domain of a Rational Function\n\nIn mathematics, a **rational function** is defined as the ratio of two polynomials, expressed in the form $f (x) = \\frac{P (x)}{Q (x)}$. A fundamental rule in algebra is that division by zero is undefined. Therefore, the domain of any rational function includes all real numbers except those values of $x$ that make the denominator, $Q (x)$, equal to zero.\n\n#### Step-by-Step Derivation:\n\n1. **Identify the denominator:** For the given function $f (x) = \\frac{x^2 - 4}{x - 2}$, the denominator is $Q (x) = x - 2$.\n2. **Set the denominator to zero:** To find the values that must be excluded from the domain, we solve the equation:\n $$x - 2 = 0$$\n3. **Solve for $x$:** Adding 2 to both sides of the equation gives:\n $$x = 2$$\n4. **Analyze the result:** Even though the numerator $x^2 - 4$ can be factored as $(x - 2)(x + 2)$, allowing the function to be simplified to $f (x) = x + 2$ for all $x \\neq 2$, the domain is determined by the **original** expression before any simplification. At $x = 2$, the original function results in the indeterminate form $\\frac{0}{0}$, which is undefined.\n\n#### Conclusion:\nSince the denominator becomes zero when $x = 2$, the function $f (x)$ is undefined at this point. Therefore, the domain of $f$ is the set of all real numbers except $2$. This confirms that **Option B** is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Relations & Functions",
      "section_instruction": "Answer question 42 based on Unit 1: Relations and Functions standards.",
