      "id": "q-exam-entrance-1789625998133-46",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 46,
      "question_text": "What is the solution set for the radical equation",
      "option_a": "{1,−4}",
      "option_b": "{1,4}",
      "option_c": "{−1,4}",
      "option_d": "{−1,−4}",
      "correct_answer": "A",
      "answer_status": "admin_verified",
      "explanation": "To solve a radical equation, we must i so late the radical, square both sides to eliminate it, and then solve the resulting polynomial equation. Crucially, we must verify all potential solutions in the original equation to ensure they are not \" extraneous \" (solutions that arise from squaring but do not satisfy the original expression).\n\n**Step-by-Step Derivation:**\n\nGiven the equation:\n$$\\sqrt{x+12} = x$$\n\n**Step 1: Square both sides to eliminate the radical.**\n$$(\\sqrt{x+12})^2 = (x)^2$$\n$$x + 12 = x^2$$\n\n**Step 2: Rearrange into a standard quadratic equation form ($ax^2 + bx + c = 0$).**\n$$x^2 - x - 12 = 0$$\n\n**Step 3: Factor the quadratic equation.**\nWe look for two numbers that multiply to $-12$ and add to $-1$. These numbers are $-4$ and $3$.\n$$(x - 4)(x + 3) = 0$$\nThis gives us two potential solutions: $x = 4$ and $x = -3$.\n\n**Step 4: Verify the solutions in the original equation.**\n* **Test $x = 4$:**\n $$\\sqrt{4 + 12} = \\sqrt{16} = 4$$\n Since $4 = 4$, $x = 4$ is a valid solution.\n* **Test $x = -3$:**\n $$\\sqrt{-3 + 12} = \\sqrt{9} = 3$$\n Since $3 \\neq -3$, $x = -3$ is an extraneous solution.\n\n*Note on the provided options:* The question asks for the solution set. Based on the algebraic derivation, the only valid solution is $\\{4\\}$. However, if the original equation was intended to be $\\sqrt{x+12} = |x|$ or if there is a typo in the provided options, we observe that the factors derived were $4$ and $-3$. Given the options provided, Option A $\\{1, -4\\}$ appears to be a mismatch with the standard interpret at i on of this specific radical equation. Based on the provided correct answer key (A), there may be a typographical error in the source question's equation or options. Following the standard mathematical procedure, $x=4$ is the only valid solution.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
