      "id": "q-exam-entrance-1789625998133-47",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 47,
      "question_text": "Using logarithm rules, which expression is equivalent to log3 (9x2)",
      "option_a": "2log3 (3x)",
      "option_b": "2+2log3 (x)",
      "option_c": "9log3 (x2)",
      "option_d": "3+2log3 (x) 2018 Maths",
      "correct_answer": "B",
      "answer_status": "admin_verified",
      "explanation": "To solve the expression $\\log_{3}(9x^2)$, we rely on two fundamental laws of logarithms:\n\n1. **The Product Rule:** $\\log_{b}(MN) = \\log_{b}(M) + \\log_{b}(N)$\n2. **The Power Rule:** $\\log_{b}(M^k) = k \\cdot \\log_{b}(M)$\n\n### Step-by-Step Derivation:\n\n**Step 1: Apply the Product Rule**\nThe expression inside the logarithm is a product of $9$ and $x^2$. We can split this into two separate logarithms:\n$$\\log_{3}(9x^2) = \\log_{3}(9) + \\log_{3}(x^2)$$\n\n**Step 2: Simplify the first term**\nWe know that $9$ can be written as a power of the base $3$, specifically $9 = 3^2$. Therefore:\n$$\\log_{3}(9) = \\log_{3}(3^2)$$\nUsing the property $\\log_{b}(b^k) = k$, we get:\n$$\\log_{3}(3^2) = 2$$\n\n**Step 3: Simplify the second term**\nUsing the Power Rule, we can bring the exponent $2$ in front of the logarithm:\n$$\\log_{3}(x^2) = 2\\log_{3}(x)$$\n\n**Step 4: Combine the results**\nSubstitute the simplified terms back into the equation from Step 1:\n$$\\log_{3}(9x^2) = 2 + 2\\log_{3}(x)$$\n\n### Conclusion:\nBy applying the product and power rules of logarithms, we have transformed $\\log_{3}(9x^2)$ into $2 + 2\\log_{3}(x)$. This matches **Option B**, which is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Limits & Continuity",
      "section_instruction": "Answer question 47 based on Unit 2: Introduction to Limits and Continuity standards.",
