      "id": "q-exam-entrance-1789625998133-49",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 49,
      "question_text": "In an arithmetic progress i on, the first term is 11 and the common difference is −13. What is the\nsum of the first 7 terms?",
      "option_a": "-28",
      "option_b": "-196",
      "option_c": "-67",
      "option_d": "196",
      "correct_answer": "B",
      "answer_status": "admin_verified",
      "explanation": "To find the sum of the first $n$ terms of an arithmetic progress i on, we use the formula for the sum of an arithmetic series:\n\n$$S_n = \\frac{n}{2} [2a + (n - 1) d]$$\n\nWhere:\n* $n$ is the number of terms.\n* $a$ is the first term.\n* $d$ is the common difference.\n\n### Step-by-Step Derivation:\n\n**1. Identify the given values:**\nFrom the problem statement, we have:\n* $n = 7$ (the number of terms to sum)\n* $a = 11$ (the first term)\n* $d = -13$ (the common difference)\n\n**2. Substitute the values into the formula:**\nPlug these values into the sum formula:\n$$S_7 = \\frac{7}{2} [2 (11) + (7 - 1)(-13)]$$\n\n**3. Simplify the expression inside the brackets:**\nFirst, calculate the terms inside the parentheses:\n$$S_7 = \\frac{7}{2} [22 + (6)(-13)]$$\n$$S_7 = \\frac{7}{2} [22 - 78]$$\n\n**4. Perform the final arithmetic:**\nSubtract the values inside the brackets:\n$$S_7 = \\frac{7}{2} [-56]$$\nNow, multiply:\n$$S_7 = 7 \\times (-28)$$\n$$S_7 = -196$$\n\n### Conclusion:\nBy applying the arithmetic series formula, we calculated the sum of the first 7 terms to be $-196$. This matches **Option B**, confirming it is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Sequences & Series",
      "section_instruction": "Answer question 49 based on Unit 1: Sequences and Series standards.",
