      "id": "q-exam-entrance-1789625998133-50",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 50,
      "question_text": "In a geometric sequence, the first term is g1=2 and the fifth term is g5=8 (assume the common\nratio is positive). What is the value of the 13th term (g13)?",
      "option_a": "32",
      "option_b": "64",
      "option_c": "128",
      "option_d": "256",
      "correct_answer": "C",
      "answer_status": "admin_verified",
      "explanation": "### Explanation of the Geometric Sequence Problem\n\nIn a geometric sequence, any term $g_n$ can be expressed using the first term $g_1$ and the common ratio $r$ by the formula:\n$$g_n = g_1 \\cdot r^{n-1}$$\n\n#### Step-by-Step Derivation:\n\n**1. Find the common ratio ($r$):**\nWe are given $g_1 = 2$ and $g_5 = 8$. Using the formula for the 5th term:\n$$g_5 = g_1 \\cdot r^{5-1}$$\n$$8 = 2 \\cdot r^4$$\nDivide both sides by 2:\n$$4 = r^4$$\nSince the problem specifies that the common ratio is positive, we take the positive fourth root:\n$$r = \\sqrt [4] {4} = \\sqrt [4] {2^2} = 2^{2/4} = 2^{1/2} = \\sqrt{2}$$\n\n**2. Calculate the 13th term ($g_{13}$):**\nNow, apply the formula for $n = 13$:\n$$g_{13} = g_1 \\cdot r^{13-1}$$\n$$g_{13} = 2 \\cdot (\\sqrt{2})^{12}$$\nSince $(\\sqrt{2})^{12} = (2^{1/2})^{12} = 2^6$:\n$$g_{13} = 2 \\cdot 2^6$$\n$$g_{13} = 2^1 \\cdot 2^6 = 2^7$$\n$$g_{13} = 128$$\n\n#### Conclusion:\nBy substituting the values into the general term formula, we determined that the common ratio is $\\sqrt{2}$ and the 13th term is $2^7$, which equals $128$. Therefore, **Choice C** is the correct answer.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Sequences & Series",
      "section_instruction": "Answer question 50 based on Unit 1: Sequences and Series standards.",
      "instruction_category": "Sequences & Series",
      "difficulty": "Medium",
