      "id": "q-exam-entrance-1789625998133-51",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 51,
      "question_text": "The infinite repeating decimal 0.373737... can be expressed as which rational fraction in lowest\nterms?",
      "option_a": "37/100",
      "option_b": "37/99",
      "option_c": "37/90",
      "option_d": "1/3",
      "correct_answer": "B",
      "answer_status": "admin_verified",
      "explanation": "To express an infinite repeating decimal as a rational fraction, we use an algebraic method that eliminates the repeating part through subtraction.\n\n### Step-by-Step Derivation\n\n**Step 1: Define the variable**\nLet $x$ represent the repeating decimal:\n$x = 0.373737...$ --- (Equation 1)\n\n**Step 2: Shift the decimal point**\nSince the repeating block consists of two digits ($37$), we multiply $x$ by $10^2$ (which is $100$) to shift the decimal point two places to the right. This aligns the repeating parts:\n$100x = 37.373737...$ --- (Equation 2)\n\n**Step 3: Subtract the equations**\nSubtract Equation 1 from Equation 2 to eliminate the infinite repeating tail:\n$(100x) - x = (37.373737...) - (0.373737...)$\n\n$99x = 37$\n\n**Step 4: Solve for $x$**\nDivide both sides by $99$ to i so late $x$:\n$x = \\frac{37}{99}$\n\n### Conclusion\nThe fraction $\\frac{37}{99}$ is already in its lowest terms because $37$ is a prime number and is not a factor of $99$. Comparing this result to the given options, we confirm that **Choice B** is the correct answer. \n\n**General Rule:** For any repeating decimal where the repetition starts immediately after the decimal point, the fraction is formed by placing the repeating block as the numerator and a sequence of $9$s (equal to the number of repeating digits) as the denominator. Here, $37$ over $99$ perfectly follows this rule.",
      "grade_id": "grade-12-natural",
