          "id": "q-exam-entrance-1789625998133-52",
          "exam_id": "exam-entrance-1789625998133",
          "question_number": 52,
          "question_text": "According to the properties of integration, which of the following is equivalent to $\\int (3f(x) - g(x))\\,dx$?",
          "option_a": "$3\\int f(x)\\,dx - \\int g(x)\\,dx$",
          "option_b": "$\\int 3f(x)\\,dx + \\int g(x)\\,dx$",
          "option_c": "$\\frac{1}{3} \\int f(x)\\,dx - \\int g(x)\\,dx$",
          "option_d": "$3\\int f(x)\\,dx \\cdot \\int g(x)\\,dx$",
          "correct_answer": "A",
          "answer_status": "admin_verified",
          "explanation": "To solve this problem, we rely on the fundamental **linearity proper ties of the indefinite integral**. The linearity property states that integration is a linear operator, meaning it satisfies two specific conditions: the **Sum/Difference Rule** and the **Constant Multiple Rule**.\n\n### Step-by-Step Derivation:\n\n1. **The Sum/Difference Rule:** This rule states that the integral of a sum or difference of two functions is equal to the sum or difference of their individual integrals. Mathematically, this is expressed as:\n $$\\int (f(x) \\pm g (x)) \\, dx = \\int f (x) \\, dx \\pm \\int g (x) \\, dx$$\n\n2. **The Constant Multiple Rule:** This rule states that a constant factor $c$ can be moved outside the integral sign. Mathematically:\n $$\\int c \\cdot f (x) \\, dx = c \\int f (x) \\, dx$$\n\n3. **Applying the Rules to the Expression:** We are given the expression $\\int (3f (x) - g (x)) \\, dx$. We apply the rules in sequence:\n * First, apply the **Difference Rule**:\n $$\\int (3f (x) - g (x)) \\, dx = \\int 3f (x) \\, dx - \\int g (x) \\, dx$$\n * Next, apply the **Constant Multiple Rule** to the first term:\n $$\\int 3f (x) \\, dx = 3 \\int f (x) \\, dx$$\n * Combining these results, we get:\n $$3 \\int f (x) \\, dx - \\int g (x) \\, dx$$\n\n### Conclusion:\nBy applying the linearity proper ties of integration, we have shown that $\\int (3f (x) - g (x)) \\, dx$ is equivalent to $3 \\int f (x) \\, dx - \\int g (x) \\, dx$. Since Option A represents this exact mathematical expansion, it is the correct choice.",
          "grade_id": "grade-12-natural",
          "subject_id": "subj-math",
          "topic_name": "Integral Calculus & Applications",
          "section_instruction": "Answer question 52 based on Unit 5: Introduction to Integral Calculus standards.",
          "instruction_category": "Integral Calculus & Applications",
          "difficulty": "Medium",
          "extraction_method": "high_fidelity_pdf_reparse",
          "extraction_confidence": 1,
          "needs_review": false,
          "is_ai_generated": false,
          "exam_title": "2018 E.C. Mathematics EUEE Exam",
          "exam_year": 2018,
          "updated_at": "2026-09-18T14:21:21.115Z",
