      "exam_id": "exam-entrance-1789625998133",
      "question_number": 54,
      "question_text": "If α and β are complementary angles (α+β=90∘), which of the following trigonometric relations\nis always true?",
      "option_a": "sin(α)=sin(β)",
      "option_b": "tan(α)=tan(β)",
      "option_c": "sin(α)=cos(β)",
      "option_d": "sec(α)=cos(β)",
      "correct_answer": "C",
      "answer_status": "admin_verified",
      "explanation": "### Explanation of Trigonometric Cofunction I dent i ties\n\nIn trigonometry, two angles are **complementary** if their sum is $90^\\circ$. The relationship between the trigonometric functions of complementary angles is defined by the **cofunction i dent i ties**. These i dent i ties state that a trigonometric function of an angle is equal to the cofunction of its complement.\n\n#### Step-by-Step Derivation:\n1. **Define the angles:** We are given that $\\alpha + \\beta = 90^\\circ$. This implies that $\\beta = 90^\\circ - \\alpha$.\n2. **Consider a Right-Angled Triangle:** Imagine a right triangle with an angle $\\alpha$. The other non-right angle must be $\\beta = 90^\\circ - \\alpha$ because the sum of angles in a triangle is $180^\\circ$.\n3. **Apply Trigonometric Definitions:**\n - By definition, $\\sin(\\alpha) = \\frac{\\text{opposite}}{\\text{hypotenuse}}$.\n - For angle $\\beta$, the side that was \" opposite \" to $\\alpha$ is now the \" adjacent \" side.\n - Therefore, $\\cos(\\beta) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{\\text{opposite}}{\\text{hypotenuse}}$.\n4. **Equate the expressions:** Since both $\\sin(\\alpha)$ and $\\cos(\\beta)$ represent the ratio of the same side (the side opposite to $\\alpha$) to the hypotenuse, we conclude that:\n $$\\sin(\\alpha) = \\cos (90^\\circ - \\alpha) = \\cos(\\beta)$$\n\n#### Analysis of Options:\n* **A:** $\\sin(\\alpha) = \\sin(\\beta)$ is only true if $\\alpha = \\beta = 45^\\circ$. It is not *always* true.\n* **B:** $\\tan(\\alpha) = \\tan(\\beta)$ is only true if $\\alpha = \\beta = 45^\\circ$.\n* **C:** $\\sin(\\alpha) = \\cos(\\beta)$ is the fundamental cofunction identity derived above and is **always true** for complementary angles.\n* **D:** $\\sec(\\alpha) = \\frac{1}{\\cos(\\alpha)}$, which is not equal to $\\cos(\\beta)$ (which is $\\sin(\\alpha)$).\n\n**Conclusion:** Choice **C** is the correct answer because it represents the standard cofunction identity for sine and cosine.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
