      "id": "q-exam-entrance-1789625998133-56",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 56,
      "question_text": "Which one of the following statements defines a matrix?",
      "option_a": "A matrix is a rectangular array of numbers.",
      "option_b": "A matrix is a vertical array of letters.",
      "option_c": "A matrix is a horizontal array of letters.",
      "option_d": "A matrix is a circular array of numbers.",
      "correct_answer": "A",
      "answer_status": "admin_verified",
      "explanation": "In mathematics, a **matrix** is a fundamental structure used to organize and manipulate data, solve systems of linear equations, and represent linear transform at i ons.\n\n### Step-by-Step Reasoning:\n\n1. **Definition of a Matrix:** A matrix is formally defined as a rectangular arrangement of numbers, symbols, or expressions, arranged in rows and columns. These elements are typically enclosed within square brackets $[ \\dots ]$ or parentheses $( \\dots )$.\n2. **Analyzing the Structure:** \n * A matrix must have a defined number of rows ($m$) and columns ($n$). This grid-like structure is what makes it \" rectangular.\"\n * While the elements inside a matrix can be variables (letters), the fundamental definition relies on the **rectangular array** structure rather than the specific type of content (numbers vs. letters).\n3. **Evaluating the Options:**\n * **Option A:** Correct. It i dent if ies the essential geometric property (rectangular array) and the standard content (numbers).\n * **Option B & C:** In correct. While matrices can contain letters, they are not restricted to being *only* vertical or *only* horizontal arrays. A single row or column is a special case, but the general definition requires a rectangular grid.\n * **Option D:** In correct. A matrix must have rows and columns that intersect at right angles. A \" circular array \" does not satisfy the algebraic proper ties required for matrix operations like add it i on or multiplication.\n\n### Conclusion:\nBecause a matrix is defined by its rectangular arrangement of elements into rows and columns, **Option A** is the only statement that accurately describes the mathematical definition of a matrix.",
      "grade_id": "grade-12-natural",
