          "id": "q-exam-entrance-1789625998133-57",
          "exam_id": "exam-entrance-1789625998133",
          "question_number": 57,
          "question_text": "Which one of the following is the decomposition of the rational expression $\\frac{3x^2 + 5x - 1}{(x+2)(x+1)^2}$ as a sum of partial fractions?",
          "option_a": "$\\frac{A}{x+2} + \\frac{B}{x+1} + \\frac{C}{(x+1)^2}$",
          "option_b": "$\\frac{A}{x+2} + \\frac{Bx + C}{(x+1)^2}$",
          "option_c": "$\\frac{A}{x+2} + \\frac{B}{(x+1)^2}$",
          "option_d": "$\\frac{Ax + B}{x+2} + \\frac{C}{x+1}$",
          "correct_answer": "A",
          "answer_status": "admin_verified",
          "explanation": "To decompose a rational expression into partial fractions, we must express it as a sum of simpler fractions based on the factors of the denominator.\n\n### Concept Explanation\nWhen a denominator contains a linear factor $(ax + b)$ raised to a power $n$, the partial fraction decomposition must include a sum of $n$ fractions with constant numerators, corresponding to each power from $1$ to $n$. For the expression $\\frac{3x^2 + 5x - 1}{(x+2)(x+1)^2}$, the denominator has one non-repeated linear factor $(x+2)$ and one repeated linear factor $(x+1)^2$.\n\n### Step-by-Step Derivation\n1. **Set up the general form:**\n Based on the rules of partial fractions, we write:\n $$\\frac{3x^2 + 5x - 1}{(x+2)(x+1)^2} = \\frac{A}{x+2} + \\frac{B}{x+1} + \\frac{C}{(x+1)^2}$$\n\n2. **Clear the denominators:**\n Multiply both sides by the common denominator $(x+2)(x+1)^2$:\n $$3x^2 + 5x - 1 = A (x+1)^2 + B (x+2)(x+1) + C (x+2)$$\n\n3. **Solve for constants:**\n * **Let $x = -1$:**\n $3(-1)^2 + 5(-1) - 1 = C(-1 + 2) \\implies 3 - 5 - 1 = C \\implies C = -3$\n * **Let $x = -2$:**\n $3(-2)^2 + 5(-2) - 1 = A(-2 + 1)^2 \\implies 12 - 10 - 1 = A (1) \\implies A = 1$\n * **Find $B$ by comparing coefficients of $x^2$:**\n The $x^2$ term on the left is $3$. On the right, it is $A + B$.\n $3 = 1 + B \\implies B = 2$\n\n4. **Final Expression:**\n Substituting the values back into the form:\n $$\\frac{1}{x+2} + \\frac{2}{x+1} - \\frac{3}{(x+1)^2}$$\n\n### Conclusion\nThe decomposition results in $\\frac{1}{x+2} + \\frac{2}{x+1} - \\frac{3}{(x+1)^2}$. This matches the structure provided in **Option A**, confirming it is the correct decomposition.",
          "grade_id": "grade-12-natural",
          "subject_id": "subj-math",
          "topic_name": "Rational Expressions & Functions",
          "section_instruction": "Answer question 57 based on Unit 2: Rational Expressions and Rational Functions standards.",
          "instruction_category": "Rational Expressions & Functions",
          "difficulty": "Medium",
          "extraction_method": "high_fidelity_pdf_reparse",
          "extraction_confidence": 1,
          "needs_review": false,
          "is_ai_generated": false,
          "exam_title": "2018 E.C. Mathematics EUEE Exam",
