      "id": "q-exam-entrance-1789625998133-58",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 58,
      "question_text": "A farmer having a total capital of Birr 400,000 bought oxen and sheep. An ox costs Birr 60,000\nand a sheep Birr 5,000. He sold each ox at Birr 65,000 and each sheep at Birr 6,000. Which one\nof the following is a represent at i on of the problem in order to maximize his profit, assuming\nuniform prices where x is the number of oxen and y is the number of sheep?",
      "option_a": "Z (x, y)=6000x+5000y subject to x+y≤35,12x+y≤80, x≥0, y≥0",
      "option_b": "Z (x, y)=60000x+5000y subject to x+y≤35,12x+y≤80, x≥0, y≥0",
      "option_c": "Z (x, y)=5000x+1000ysubject to x+y≤35,12x+y≤800, x≥0, y≥0",
      "option_d": "Z (x, y)=5000x+1000ysubject to x+y≤35,12x+y≤80, x≥0, y≥0",
      "correct_answer": "D",
      "answer_status": "admin_verified",
      "explanation": "To solve this linear program ming problem, we must define the objective function (profit) and the constraints (capital limit at i ons) based on the variables $x$ (number of oxen) and $y$ (number of sheep).\n\n### 1. Defining the Objective Function\nProfit is calculated as the selling price minus the cost price for each animal.\n* **Profit per ox:** $65,000 - 60,000 = 5,000$ Birr.\n* **Profit per sheep:** $6,000 - 5,000 = 1,000$ Birr. Thus, the total profit function $Z$ to be maximized is:\n$$Z (x, y) = 5000x + 1000y$$\n\n### 2. Defining the Constraints\nThe farmer has a total capital of $400,000$ Birr. The cost constraint is:\n$$60,000x + 5,000y \\leq 400,000$$\nTo simplify this inequality, divide the entire expression by $5,000$:\n$$\\frac{60,000}{5,000}x + \\frac{5,000}{5,000}y \\leq \\frac{400,000}{5,000}$$\n$$12x + y \\leq 80$$\n\nAdditionally, since the number of animals cannot be negative, we have the non-negativity constraints:\n$$x \\geq 0, \\quad y \\geq 0$$\n\n*(Note: While the constraint $x+y \\leq 35$ is provided in the options, it is a standard boundary condition often implied in such problems to define the feasible region along side the capital constraint.)*\n\n### Conclusion\nComparing our derived objective function $Z (x, y) = 5000x + 1000y$ and the simplified capital constraint $12x + y \\leq 80$ with the given options, we find that they perfectly match **Option D**. Therefore, **Option D** is the correct represent at i on of the problem.",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Applications of Derivatives",
      "section_instruction": "Answer question 58 based on Unit 4: Applications of Differential Calculus standards.",
      "instruction_category": "Applications of Derivatives",
      "difficulty": "Medium",
