      "id": "q-exam-entrance-1789625998133-59",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 59,
      "question_text": "2018 Maths\nWhich one of the following statements is true about the given numbers and points on the\nnumber line?",
      "option_a": "There is a one-to-one correspondence between the set of natural numbers and points on the\nnumber line.",
      "option_b": "There is a one-to-one correspondence between the set of rational numbers and points on\nthe number line.",
      "option_c": "There is a one-to-one correspondence between the set of irrational numbers and points on\nthe number line.",
      "option_d": "There is a one-to-one correspondence between the set of real numbers and points on the\nnumber line.",
      "correct_answer": "D",
      "answer_status": "admin_verified",
      "explanation": "To understand this question, we must look at the fundamental relationship between the set of real numbers ($\\mathbb{R}$) and the geometric represent at i on of the number line.\n\n### Concept Explanation\nIn mathematics, a **one-to-one correspondence** (or bijection) exists between two sets if every element in the first set is paired with exactly one element in the second set, and vice versa. The \" Real Number Line \" is defined specifically as a geometric line where every point corresponds to a unique real number, and every real number corresponds to a unique point on the line. This is known as the **Completeness Axiom** of the real numbers.\n\n### Logical Derivation\n1. **Natural Numbers ($\\mathbb{N}$):** The set $\\{1, 2, 3, ...\\}$ is discrete. There are infinite gaps between these numbers on the number line (e.g., there is no natural number between 1 and 2). Thus, they cannot cover all points on the line.\n2. **Rational Numbers ($\\mathbb{Q}$):** While rational numbers are \" dense \" (between any two rationals, there is another rational), they are not \" complete.\" There are \" holes \" in the rational number line where irrational numbers (like $\\sqrt{2}$ or $\\pi$) reside. Therefore, they do not map to every point on the line.\n3. **Irrational Numbers ($\\mathbb{I}$):** Similarly, the set of irrational numbers leaves out all rational numbers. They do not account for every point on the line.\n4. **Real Numbers ($\\mathbb{R}$):** The set of real numbers includes both rational and irrational numbers. By definition, the real number line is constructed such that there are no gaps. Every point on the line represents a real number, and every real number has a specific location on the line.\n\n### Conclusion\nBecause the set of real numbers is both dense and complete, it perfectly fills the number line without any gaps or overlaps. Therefore, there is a one-to-one correspondence between the set of real numbers and the points on the number line. \n\n**Choice D is the correct statement.**",
      "grade_id": "grade-12-natural",
      "subject_id": "subj-math",
      "topic_name": "Relations & Functions",
      "section_instruction": "Answer question 59 based on Unit 1: Relations and Functions standards.",
      "instruction_category": "Relations & Functions",
      "difficulty": "Medium",
      "extraction_method": "high_fidelity_pdf_reparse",
      "extraction_confidence": 1,
      "needs_review": false,
      "is_ai_generated": false,
