      "id": "q-exam-entrance-1789625998133-60",
      "exam_id": "exam-entrance-1789625998133",
      "question_number": 60,
      "question_text": "A spherical ball has diameter 30cm. What is its surface area (in cm2)?",
      "option_a": "3600π",
      "option_b": "1000π",
      "option_c": "900π",
      "option_d": "600π",
      "correct_answer": "C",
      "answer_status": "admin_verified",
      "explanation": "To find the surface area of a spherical ball, we must use the geometric proper ties of a sphere. The surface area $A$ of a sphere is determined by the formula:\n\n$$A = 4\\pi r^2$$\n\nwhere $r$ represents the radius of the sphere.\n\n### Step-by-Step Derivation:\n\n**1. Identify the given information:**\nThe problem provides the diameter $d$ of the spherical ball, which is $30 \\text{ cm}$.\n\n**2. Calculate the radius:**\nThe radius $r$ of a sphere is exactly half of its diameter. Therefore:\n$$r = \\frac{d}{2}$$\n$$r = \\frac{30 \\text{ cm}}{2} = 15 \\text{ cm}$$\n\n**3. Substitute the radius into the surface area formula:**\nNow, substitute $r = 15$ into the formula $A = 4\\pi r^2$:\n$$A = 4 \\cdot \\pi \\cdot (15)^2$$\n\n**4. Perform the arithmetic:**\nFirst, calculate the square of the radius:\n$$15^2 = 225$$\nNext, multiply this result by 4:\n$$A = 4 \\cdot \\pi \\cdot 225$$\n$$A = 900\\pi$$\n\n### Conclusion:\nBy calculating the square of the radius and multiplying by the constant factor of 4, we find that the surface area of the sphere is $900\\pi \\text{ cm}^2$. Comparing this result to the given options, it is clear that **Choice C** is the correct answer.",
      "grade_id": "grade-12-natural",
