          "question_text": "A cell containing $\\text{AlCl}_3$ as an electrolyte is placed in series with another cell containing $\\text{AgNO}_3$ as an electrolyte. What mass of $\\text{Ag}$ is deposited when $18\\text{ g}$ of $\\text{Al}$ is deposited at the cathode electrode? ($M_{\\text{Ag}} = 108\\text{ g/mol}$ and $M_{\\text{Al}} = 27\\text{ g/mol}$)",
