          "explanation": "Using Faraday's Second Law of Electrolysis: $$\\frac{m_1}{E_1} = \\frac{m_2}{E_2}$$ * Equivalent weight of $\\text{Al}$ ($E_{\\text{Al}}$) = $\\frac{\\text{Molar Mass}}{n} = \\frac{27}{3} = 9\\text{ g/eq}$ * Equivalent weight of $\\text{Ag}$ ($E_{\\text{Ag}}$) = $\\frac{\\text{Molar Mass}}{n} = \\frac{108}{1} = 108\\text{ g/eq}$ $$\\frac{m_{\\text{Al}}}{E_{\\text{Al}}} = \\frac{m_{\\text{Ag}}}{E_{\\text{Ag}}} \\implies \\frac{18\\text{ g}}{9\\text{ g/eq}} = \\frac{m_{\\text{Ag}}}{108\\text{ g/eq}}$$ $$2 = \\frac{m_{\\text{Ag}}}{108} \\implies m_{\\text{Ag}} = 216\\text{ g}$$",
