          "exam_id": "exam-entrance-1789446267047",
          "question_number": 7,
          "question_text": "What is the concentration of hydrogen ion in a solution of $0.1\\text{ M}$ nicotinic acid, $\\text{HC}_6\\text{H}_4\\text{NO}_2$, at 25°C? ($K_a = 1.4 \\times 10^{-5}$)",
          "option_a": "$1.2 \\times 10^{-5}\\text{ M}$",
