          "correct_answer": "B",
          "explanation": "Nicotinic acid is a weak monoprotic acid ($\\text{HA} \\rightleftharpoons \\text{H}^+ + \\text{A}^-$). Since $C_0 / K_a = 0.1 / (1.4 \\times 10^{-5}) \\gg 400$, we apply the approximation: $$[\\text{H}^+] = \\sqrt{K_a \\cdot C_0} = \\sqrt{(1.4 \\times 10^{-5}) \\cdot 0.1} = \\sqrt{1.4 \\times 10^{-6}}$$ $$[\\text{H}^+] \\approx 1.183 \\times 10^{-3}\\text{ M} \\approx 1.2 \\times 10^{-3}\\text{ M}$$",
