          "question_number": 8,
          "question_text": "Chlorine has two naturally occurring isotopes. In a sample of chlorine, 25% of the atoms are Cl-37 and 75% of the atoms are Cl-35. What is the average atomic mass of chlorine?",
          "option_a": "26.25",
          "option_b": "25.75",
