          "question_number": 15,
          "question_text": "What is the amount of energy emitted when an electron moves from the $n=4$ to $n=2$ energy level? ($R_H = 2.18 \\times 10^{-18}\\text{ J}$)",
          "option_a": "$-6.54 \\times 10^{-18}\\text{ J}$",
          "option_b": "$-4.09 \\times 10^{-19}\\text{ J}$",
          "option_c": "$4.09 \\times 10^{-19}\\text{ J}$",
          "option_d": "$6.54 \\times 10^{-18}\\text{ J}$",
          "correct_answer": "C",
          "explanation": "The energy emitted during an electronic transition in a hydrogenic atom is given by: $$\\Delta E = R_H \\left( \\frac{1}{n_f^2} - \\frac{1}{n_i^2} \\right)$$ $$\\Delta E = 2.18 \\times 10^{-18}\\text{ J} \\left( \\frac{1}{2^2} - \\frac{1}{4^2} \\right) = 2.18 \\times 10^{-18} \\left( \\frac{1}{4} - \\frac{1}{16} \\right)$$ $$\\Delta E = 2.18 \\times 10^{-18} \\left( \\frac{3}{16} \\right) = 4.0875 \\times 10^{-19}\\text{ J} \\approx 4.09 \\times 10^{-19}\\text{ J}$$",
          "difficulty": "Medium",
