          "question_text": "Consider the following equilibrium reaction of a certain weak acid, $\\text{RCOOH}$: $$\\text{RCOOH}(aq) + \\text{H}_2\\text{O}(l) \\rightleftharpoons \\text{RCOO}^-(aq) + \\text{H}_3\\text{O}^+(aq)$$ Which of the following is the CORRECT expression of the percent ionization of $\\text{RCOOH}$?",
