          "exam_id": "exam-entrance-1789446267047",
          "question_number": 28,
          "question_text": "Consider the following electrochemical reaction: $$\\text{Cu}(s) + 2\\text{Ce}^{4+}(aq) \\rightleftharpoons \\text{Cu}^{2+}(aq) + 2\\text{Ce}^{3+}(aq)$$ Which of the following effects increases the cell potential of the reaction?",
          "option_a": "Decreasing concentration of $\\text{Cu}(s)$",
          "option_b": "Increasing concentration of $\\text{Cu}^{2+}$",
          "option_c": "Increasing concentration of $\\text{Ce}^{3+}$",
