          "exam_id": "exam-entrance-1789446267047",
          "question_number": 35,
          "question_text": "If a $50\\text{ cm}^3$ sample of gas exerts a pressure of $60.0\\text{ kPa}$ at $35^\\circ\\text{C}$, what volume will it occupy at STP ($0^\\circ\\text{C}$ and $1\\text{ atm} = 101.325\\text{ kPa}$) in $\\text{cm}^3$?",
          "option_a": "226.86",
          "option_b": "234.0",
          "option_c": "26.24",
          "option_d": "265.0",
          "correct_answer": "C",
          "explanation": "Using the Combined Gas Law: $$\\frac{P_1 V_1}{T_1} = \\frac{P_2 V_2}{T_2}$$ * $P_1 = 60.0\\text{ kPa}$, $V_1 = 50\\text{ cm}^3$, $T_1 = 35 + 273.15 = 308.15\\text{ K}$ * $P_2 = 101.325\\text{ kPa}$, $T_2 = 273.15\\text{ K}$ $$V_2 = \\frac{P_1 V_1 T_2}{P_2 T_1} = \\frac{(60.0) \\times (50) \\times (273.15)}{(101.325) \\times (308.15)} = \\frac{819450}{31223.4} \\approx 26.24\\text{ cm}^3$$",
          "difficulty": "Medium",
          "topic_id": "top-chem-35",
          "topic_name": "Gas Laws & Combined Gas Equation",
          "subject_id": "subj-chem",
          "grade_id": "grade-12-natural",
          "points": 1.25,
          "has_diagram": false,
          "created_at": "2026-10-28T06:32:11.287Z"
