          "id": "q-exam-entrance-1789446267047-53",
          "exam_id": "exam-entrance-1789446267047",
          "question_number": 53,
          "question_text": "An equilibrium mixture contains $0.30\\text{ mol }\\text{CO}$, $0.10\\text{ mol }\\text{H}_2$, $0.020\\text{ mol }\\text{H}_2\\text{O}$ and an unknown concentration of $\\text{CH}_4$, in a $1.0\\text{ L}$ container at $1200\\text{ K}$. In this mixture, what is the molar concentration of $\\text{CH}_4$ at equilibrium? $$\\text{CO}(g) + 3\\text{H}_2(g) \\rightleftharpoons \\text{CH}_4(g) + \\text{H}_2\\text{O}(g), \\quad K_c = 3.92$$",
          "option_a": "$0.059\\text{ mol/L}$",
          "option_b": "$0.015\\text{ mol/L}$",
          "option_c": "$0.197\\text{ mol/L}$",
          "option_d": "$0.001\\text{ mol/L}$",
          "correct_answer": "A",
          "explanation": "Set up the equilibrium constant expression: $$K_c = \\frac{[\\text{CH}_4][\\text{H}_2\\text{O}]}{[\\text{CO}][\\text{H}_2]^3}$$ Substitute given values ($V = 1.0\\text{ L}$ means $\\text{moles} = \\text{molarity}$): $$3.92 = \\frac{[\\text{CH}_4](0.020)}{(0.30)(0.10)^3} = \\frac{0.020 [\\text{CH}_4]}{(0.30)(0.001)} = \\frac{0.020 [\\text{CH}_4]}{0.0003}$$ $$0.020 [\\text{CH}_4] = 3.92 \\times 0.0003 = 0.001176$$ $$[\\text{CH}_4] = \\frac{0.001176}{0.020} = 0.0588\\text{ M} \\approx 0.059\\text{ mol/L}$$",
          "difficulty": "Hard",
          "topic_id": "top-chem-53",
          "topic_name": "Chemical Equilibrium Calculations",
          "subject_id": "subj-chem",
          "grade_id": "grade-12-natural",
          "points": 1.25,
          "has_diagram": false,
