          "exam_id": "exam-entrance-1789446267047",
          "question_number": 55,
          "question_text": "The thermal decomposition of calcium carbonate during the commercial preparation of lime ($\\text{CaO}$) is given below: $$\\text{CaCO}_3(s) \\rightarrow \\text{CaO}(s) + \\text{CO}_2(g)$$ What is the atom economy for the preparation of lime based on the above reaction? (Atomic masses: $\\text{Ca}=40$, $\\text{C}=12$, $\\text{O}=16\\text{ g/mol}$)",
          "option_a": "56%",
          "option_b": "49.1%",
          "option_c": "44%",
          "option_d": "100%",
          "correct_answer": "A",
          "explanation": "$$\\text{Atom Economy} = \\left( \\frac{\\text{Molar mass of desired product}}{\\text{Total molar mass of reactants}} \\right) \\times 100\\%$$ * Desired product ($\\text{CaO}$): $40 + 16 = 56\\text{ g/mol}$ * Reactant ($\\text{CaCO}_3$): $40 + 12 + (3 \\times 16) = 100\\text{ g/mol}$ $$\\text{Atom Economy} = \\left( \\frac{56}{100} \\right) \\times 100\\% = 56\\%$$",
