          "question_number": 57,
          "question_text": "Calculate the electromotive force (EMF) of the cell $\\text{Zn}|\\text{Zn}^{2+}(0.01\\text{M})||\\text{Cu}^{2+}(1.0\\text{M})|\\text{Cu}$ at $25^\\circ\\text{C}$ ($E^\\circ_{\\text{cell}} = 1.10\\text{ V}$).",
          "option_a": "$1.10\\text{ V}$",
          "option_b": "$1.04\\text{ V}$",
          "option_c": "$1.16\\text{ V}$",
          "option_d": "$1.22\\text{ V}$",
          "correct_answer": "C",
          "explanation": "By the Nernst equation ($n=2$): $$E = E^\\circ - \\frac{0.0592}{n} \\log Q = 1.10 - \\frac{0.0592}{2} \\log \\left( \\frac{[\\text{Zn}^{2+}]}{[\\text{Cu}^{2+}]} \\right)$$ $$E = 1.10 - 0.0296 \\log\\left(\\frac{0.01}{1.0}\\right) = 1.10 - 0.0296 (-2) = 1.10 + 0.0592 = 1.1592\\text{ V} \\approx 1.16\\text{ V}$$",
