          "exam_id": "exam-entrance-1789446267047",
          "question_number": 58,
          "question_text": "What is the pH of a buffer solution prepared by mixing $50.0\\text{ mL}$ of $0.20\\text{ M } \\text{CH}_3\\text{COOH}$ and $50.0\\text{ mL}$ of $0.10\\text{ M } \\text{NaOH}$? ($K_a \\text{ for } \\text{CH}_3\\text{COOH} = 1.8 \\times 10^{-5}$)",
          "option_a": "2.87",
          "option_b": "4.74",
          "option_c": "5.04",
          "option_d": "9.26",
