          "explanation": "Moles initial: * $\\text{CH}_3\\text{COOH} = 0.050\\text{ L} \\times 0.20\\text{ M} = 0.010\\text{ mol}$ * $\\text{NaOH} = 0.050\\text{ L} \\times 0.10\\text{ M} = 0.005\\text{ mol}$ Neutralization reaction: $$\\text{CH}_3\\text{COOH} + \\text{OH}^- \\rightarrow \\text{CH}_3\\text{COO}^- + \\text{H}_2\\text{O}$$ * Remaining $\\text{CH}_3\\text{COOH} = 0.010 - 0.005 = 0.005\\text{ mol}$ * Formed $\\text{CH}_3\\text{COO}^- = 0.005\\text{ mol}$ Since $[\\text{Acid}] = [\\text{Conjugate Base}]$, using Henderson-Hasselbalch: $$\\text{pH} = \\text{p}K_a + \\log\\left(\\frac{[\\text{Base}]}{[\\text{Acid}]}\\right) = \\text{p}K_a + \\log(1) = \\text{p}K_a$$ $$\\text{pH} = -\\log(1.8 \\times 10^{-5}) \\approx 4.74$$",
