      "option_d": "did",
      "correct_answer": "C",
      "explanation": "The causative verb \" make \" takes a bare infinitive (make + person + base verb) in active voice. Thus, \" made the students do \" is correct. Options A, B, and D are ungrammatical after causative \" make \".",
