      "option_b": "told",
      "option_c": "has told",
      "option_d": "had told",
      "correct_answer": "D",
      "explanation": "This is a Mixed Conditional sentence connecting an unreal past action with a present result. Structure: If + Past Perfect (had told), would/wouldn't + base verb (wouldn't be) now. Option D is correct. Options A, B, and C fail to express past unreal condition.",
      "difficulty": "Medium",
